-- Migration (Regenerated): Seed formation_progressions

INSERT OR REPLACE INTO formation_progressions (
  id, formation_id, stage, simplified_content, memory_portion, parent_teaching_note
) VALUES
('wsc_q2_seedling', 'wsc_q2', 'seedling', 'God gave us the Bible to teach us.', 'The Bible is God''s Word.', 'Hold the Bible. Kiss it. Show it is special. God speaks here.'),
('wsc_q2_sprout', 'wsc_q2', 'sprout', 'Q: How do we know how to love God?\nA: God gave us the Bible.', 'The Bible is the only rule.', 'Explain "Rule" means a straight line—the Bible keeps us straight.'),
('wsc_q2_sapling', 'wsc_q2', 'sapling', 'Q: What rule hath God given to direct us how we may glorify and enjoy him?\nA: The Word of God, which is contained in the Scriptures of the Old and New Testaments, is the only rule to direct us how we may glorify and enjoy him.', 'The Word of God is the only rule.', 'Focus on "Old and New Testaments" as the two parts of one book.'),
('wsc_q2_tree', 'wsc_q2', 'tree', 'Q: What rule hath God given to direct us how we may glorify and enjoy him?\nA: The Word of God, which is contained in the Scriptures of the Old and New Testaments, is the only rule to direct us how we may glorify and enjoy him.', 'Scripture is the only rule.', 'Discuss Sola Scriptura: Tradition is helpful, but Scripture is King.'),
('wsc_q2_oak', 'wsc_q2', 'oak', 'Q: What rule hath God given to direct us how we may glorify and enjoy him?\nA: The Word of God, which is contained in the Scriptures of the Old and New Testaments, is the only rule to direct us how we may glorify and enjoy him.\n(2 Tim 3:16, Eph 2:20)', 'The Bible is our final authority.', 'Apologetics: Why do we trust the Bible? It validates itself and carries God''s authority.'),
('wsc_q3_seedling', 'wsc_q3', 'seedling', 'The Bible teaches us to love God and obey Him.', 'Believe God and Obey God.', 'Two hands: One for Believing (Heart), One for Obeying (Actions).'),
('wsc_q3_sprout', 'wsc_q3', 'sprout', 'Q: What does the Bible teach us?\nA: What to believe about God and what God wants us to do.', 'Faith and Duty.', 'The Bible isn''t just stories; it tells us who God is and how to live.'),
('wsc_q3_sapling', 'wsc_q3', 'sapling', 'Q: What do the scriptures principally teach?\nA: The scriptures principally teach what man is to believe concerning God, and what duty God requires of man.', 'Believe concerning God, Duty required.', 'Define "Principally" = Mainly. "Duty" = Responsibility.'),
('wsc_q3_tree', 'wsc_q3', 'tree', 'Q: What do the scriptures principally teach?\nA: The scriptures principally teach what man is to believe concerning God, and what duty God requires of man.', 'Faith and Obedience.', 'Doctrine leads to Doxology (Worship) and Duty (Life).'),
('wsc_q3_oak', 'wsc_q3', 'oak', 'Q: What do the scriptures principally teach?\nA: The scriptures principally teach what man is to believe concerning God, and what duty God requires of man.\n(2 Tim 1:13)', 'Faith and Life.', 'Apologetics: The Bible is sufficient for faith and practice. We don''t need new revelations.'),
('wsc_q5_seedling', 'wsc_q5', 'seedling', 'There is only one true God.', 'One God.', 'Show one finger. "How many Gods? One!"'),
('wsc_q5_sprout', 'wsc_q5', 'sprout', 'Q: Are there more Gods than one?\nA: No, there is only one living and true God.', 'One living and true God.', 'Contrast with idols (statues that can''t see/hear).'),
('wsc_q5_sapling', 'wsc_q5', 'sapling', 'Q: Are there more Gods than one?\nA: There is but one only, the living and true God.', 'One only, living and true.', 'Define "Living" (Active, alive) vs "Dead" idols.'),
('wsc_q5_tree', 'wsc_q5', 'tree', 'Q: Are there more Gods than one?\nA: There is but one only, the living and true God.', 'God is One.', 'Discuss how the world has many "gods" (money, fame), but only One is essential.'),
('wsc_q5_oak', 'wsc_q5', 'oak', 'Q: Are there more Gods than one?\nA: There is but one only, the living and true God.\n(Deut 6:4, Jer 10:10)', 'The Lord our God is one.', 'Apologetics: The logic of Monotheism. There can only be one Supreme Being.'),
('wsc_q6_seedling', 'wsc_q6', 'seedling', 'God is Father, Son, and Holy Spirit.', 'Father, Son, Holy Spirit.', 'Use a shamrock or triangle analogy if helpful, or just list the Names.'),
('wsc_q6_sprout', 'wsc_q6', 'sprout', 'Q: How many persons are in God?\nA: Three: The Father, the Son, and the Holy Spirit.', 'Three Persons, One God.', 'They are not three gods, but three persons in one God.'),
('wsc_q6_sapling', 'wsc_q6', 'sapling', 'Q: How many persons are there in the Godhead?\nA: There are three persons in the Godhead; the Father, the Son, and the Holy Ghost; and these three are one God, the same in substance, equal in power and glory.', 'Same substance, equal power.', 'Define "Godhead" (Divinity) and "Substance" (Essence).'),
('wsc_q6_tree', 'wsc_q6', 'tree', 'Q: How many persons are there in the Godhead?\nA: There are three persons in the Godhead; the Father, the Son, and the Holy Ghost; and these three are one God, the same in substance, equal in power and glory.', 'Three Persons, One God.', 'Mystery of the Trinity: Distinct persons, same essence. Not 1+1+1=3, but 1x1x1=1.'),
('wsc_q6_oak', 'wsc_q6', 'oak', 'Q: How many persons are there in the Godhead?\nA: There are three persons in the Godhead; the Father, the Son, and the Holy Ghost; and these three are one God, the same in substance, equal in power and glory.\n(Matt 28:19, 1 John 5:7)', 'Equal in power and glory.', 'Apologetics: Defending the Trinity against modalism (masks) or tritheism (three gods).'),
('wsc_q7_seedling', 'wsc_q7', 'seedling', 'God planned everything before He made the world.', 'God has a plan.', 'God is never surprised. He knows the end from the beginning.'),
('wsc_q7_sprout', 'wsc_q7', 'sprout', 'Q: Does God have a plan?\nA: Yes, God planned everything that happens for His glory.', 'For His own glory.', 'Why did God make a plan? To show how great He is.'),
('wsc_q7_sapling', 'wsc_q7', 'sapling', 'Q: What are the decrees of God?\nA: The decrees of God are, his eternal purpose, according to the counsel of his will, whereby, for his own glory, he hath foreordained whatsoever comes to pass.', 'He hath foreordained whatsoever comes to pass.', 'Vocabulary: "Decree" (Law/Order), "Foreordained" (Ordered beforehand).'),
('wsc_q7_tree', 'wsc_q7', 'tree', 'Q: What are the decrees of God?\nA: The decrees of God are, his eternal purpose, according to the counsel of his will, whereby, for his own glory, he hath foreordained whatsoever comes to pass.', 'God''s purpose stands.', 'God is Sovereign. Nothing happens by accident.'),
('wsc_q7_oak', 'wsc_q7', 'oak', 'Q: What are the decrees of God?\nA: The decrees of God are, his eternal purpose, according to the counsel of his will, whereby, for his own glory, he hath foreordained whatsoever comes to pass.\n(Eph 1:11, Rom 11:36)', 'According to His will.', 'Apologetics: How Sovereignty relates to human responsibility. God is King, we are responsible subjects.'),
('wsc_q8_seedling', 'wsc_q8', 'seedling', 'God makes His plan happen.', 'God does His plan.', 'God didn''t just make a plan and leave; He is working right now.'),
('wsc_q8_sprout', 'wsc_q8', 'sprout', 'Q: How does God do His plan?\nA: By making everything and taking care of everything.', 'Creation and Providence.', 'Creation = Making. Providence = Taking Care/Ruling.'),
('wsc_q8_sapling', 'wsc_q8', 'sapling', 'Q: How doth God execute his decrees?\nA: God executeth his decrees in the works of creation and providence.', 'Creation and Providence.', 'Two ways God works: Making the stage (Creation) and directing the play (Providence).'),
('wsc_q8_tree', 'wsc_q8', 'tree', 'Q: How doth God execute his decrees?\nA: God executeth his decrees in the works of creation and providence.', 'Works of Creation and Providence.', 'Distinguish between God''s singular act (Creation) and continuous act (Providence).'),
('wsc_q8_oak', 'wsc_q8', 'oak', 'Q: How doth God execute his decrees?\nA: God executeth his decrees in the works of creation and providence.\n(Rev 4:11, Dan 4:35)', 'He executes His decrees.', 'Apologetics: History is not random. It is "His Story".'),
('wsc_q9_seedling', 'wsc_q9', 'seedling', 'God made the whole world from nothing.', 'God made everything.', 'Look at the sky, trees, hands. God made them all.'),
('wsc_q9_sprout', 'wsc_q9', 'sprout', 'Q: What is the work of creation?\nA: God made all things of nothing, very good.', 'Out of nothing.', 'Imagine making a cookie without ingredients. Only God can do that.'),
('wsc_q9_sapling', 'wsc_q9', 'sapling', 'Q: What is the work of creation?\nA: The work of creation is, God''s making all things of nothing, by the word of his power, in the space of six days, and all very good.', 'By the word of His power.', 'He spoke, and it happened. "Let there be light."'),
('wsc_q9_tree', 'wsc_q9', 'tree', 'Q: What is the work of creation?\nA: The work of creation is, God''s making all things of nothing, by the word of his power, in the space of six days, and all very good.', 'All very good.', 'Creation was perfect originally. Sin messed it up later.'),
('wsc_q9_oak', 'wsc_q9', 'oak', 'Q: What is the work of creation?\nA: The work of creation is, God''s making all things of nothing, by the word of his power, in the space of six days, and all very good.\n(Gen 1:1, Heb 11:3)', 'Space of six days.', 'Apologetics: "Creatio Ex Nihilo" (Creation out of nothing). Matter is not eternal; only God is.'),
('wsc_q10_seedling', 'wsc_q10', 'seedling', 'God made people special.', 'God made me special.', 'You are not an accident. God made you to love Him.'),
('wsc_q10_sprout', 'wsc_q10', 'sprout', 'Q: How did God create man?\nA: Male and female, in His own image.', 'Male and female.', 'Boys and girls are both made to look like God in their hearts.'),
('wsc_q10_sapling', 'wsc_q10', 'sapling', 'Q: How did God create man?\nA: God created man male and female, after his own image, in knowledge, righteousness, and holiness, with dominion over the creatures.', 'Knowledge, righteousness, holiness.', 'We were made smart, good, and holy—like a mirror of God.'),
('wsc_q10_tree', 'wsc_q10', 'tree', 'Q: How did God create man?\nA: God created man male and female, after his own image, in knowledge, righteousness, and holiness, with dominion over the creatures.', 'Dominion over creatures.', 'Stewardship: We are kings and queens of creation, under God.'),
('wsc_q10_oak', 'wsc_q10', 'oak', 'Q: How did God create man?\nA: God created man male and female, after his own image, in knowledge, righteousness, and holiness, with dominion over the creatures.\n(Gen 1:26-27, Col 3:10)', 'Image of God.', 'Apologetics: Human dignity comes from being made in God''s image. This is why racism/murder are wrong.'),
('wsc_q12_seedling', 'wsc_q12', 'seedling', 'God put Adam in a beautiful garden. God told Adam to obey.', 'Obey God.', 'Show pictures of a garden. Emphasize that God gave Adam a wonderful home and a simple rule.'),
('wsc_q12_sprout', 'wsc_q12', 'sprout', 'Q: What did God tell Adam in the garden?\nA: God gave Adam one rule: Do not eat from one tree. If you obey, you will live.', 'One rule to obey.', 'Use the concept of "Mommy/Daddy gives us rules for our good."'),
('wsc_q12_sapling', 'wsc_q12', 'sapling', 'Q: What special act of providence did God exercise toward man in the estate wherein he was created?\nA: When God had created man, he entered into a covenant of life with him, upon condition of perfect obedience; forbidding him to eat of the tree of the knowledge of good and evil, upon the pain of death.', 'Covenant of life, perfect obedience.', 'Define "Covenant" = a promise agreement. Obey perfectly = live. Disobey = die.'),
('wsc_q12_tree', 'wsc_q12', 'tree', 'Q: What special act of providence did God exercise toward man in the estate wherein he was created?\nA: When God had created man, he entered into a covenant of life with him, upon condition of perfect obedience; forbidding him to eat of the tree of the knowledge of good and evil, upon the pain of death.', 'Perfect obedience was required.', 'Discuss how Adam represented all humanity. His obedience or disobedience would affect everyone.'),
('wsc_q12_oak', 'wsc_q12', 'oak', 'Q: What special act of providence did God exercise toward man in the estate wherein he was created?\nA: When God had created man, he entered into a covenant of life with him, upon condition of perfect obedience; forbidding him to eat of the tree of the knowledge of good and evil, upon the pain of death.\n(Gen 2:16-17, Gal 3:12, Rom 10:5)', 'Covenant of life, pain of death.', 'Apologetics: The "Works Principle" shows salvation cannot come by human effort. Adam failed; only Christ the second Adam could succeed.'),
('wsc_q13_seedling', 'wsc_q13', 'seedling', 'Adam and Eve did not listen to God. They ate the fruit.', 'They disobeyed God.', 'This is a sad story. Adam and Eve made a very bad choice.'),
('wsc_q13_sprout', 'wsc_q13', 'sprout', 'Q: Did Adam and Eve stay good?\nA: No, they disobeyed God. They sinned by eating the forbidden fruit.', 'They sinned.', 'Ask: "What happens when we disobey Mommy and Daddy?" Lead to: disobedience has consequences.'),
('wsc_q13_sapling', 'wsc_q13', 'sapling', 'Q: Did our first parents continue in the estate wherein they were created?\nA: Our first parents, being left to the freedom of their own will, fell from the estate wherein they were created, by sinning against God.', 'They fell by sinning against God.', 'Define "Fell" = to fall from a high place. They went from blessed to cursed.'),
('wsc_q13_tree', 'wsc_q13', 'tree', 'Q: Did our first parents continue in the estate wherein they were created?\nA: Our first parents, being left to the freedom of their own will, fell from the estate wherein they were created, by sinning against God.', 'Fell from the estate by sinning.', 'Discuss "freedom of will" - God didn''t force them to sin. They chose wrongly. This is the root of all human misery.'),
('wsc_q13_oak', 'wsc_q13', 'oak', 'Q: Did our first parents continue in the estate wherein they were created?\nA: Our first parents, being left to the freedom of their own will, fell from the estate wherein they were created, by sinning against God.\n(Gen 3:6-8, Eccl 7:29, Rom 5:12)', 'Left to freedom of their own will.', 'Apologetics: This answers the problem of evil. God created beings with real choice. Evil entered by creaturely rebellion, not by divine authorship.');

INSERT OR REPLACE INTO formation_progressions (
  id, formation_id, stage, simplified_content, memory_portion, parent_teaching_note
) VALUES
('wsc_q15_seedling', 'wsc_q15', 'seedling', 'Adam and Eve ate the fruit God said no to.', 'They ate the fruit.', 'The fruit looked good, but God said no. Obedience matters more than what looks nice.'),
('wsc_q15_sprout', 'wsc_q15', 'sprout', 'Q: What did Adam and Eve do wrong?\nA: They ate the fruit God told them not to eat.', 'Eating the forbidden fruit.', 'Simple disobedience. God said "no" and they said "yes, I want it anyway."'),
('wsc_q15_sapling', 'wsc_q15', 'sapling', 'Q: What was the sin whereby our first parents fell from the estate wherein they were created?\nA: The sin whereby our first parents fell from the estate wherein they were created, was their eating the forbidden fruit.', 'Eating the forbidden fruit.', 'The act seems small, but the meaning was huge: they trusted the serpent over God.'),
('wsc_q15_tree', 'wsc_q15', 'tree', 'Q: What was the sin whereby our first parents fell from the estate wherein they were created?\nA: The sin whereby our first parents fell from the estate wherein they were created, was their eating the forbidden fruit.', 'Eating the forbidden fruit.', 'Behind the eating was unbelief, pride, and coveting. One simple act contained many sins within it.'),
('wsc_q15_oak', 'wsc_q15', 'oak', 'Q: What was the sin whereby our first parents fell from the estate wherein they were created?\nA: The sin whereby our first parents fell from the estate wherein they were created, was their eating the forbidden fruit.\n(Gen 3:6, 12-13)', 'The forbidden fruit.', 'Apologetics: The simplicity of the command magnifies the gravity of the sin. They had only one prohibition, yet they broke it. This reveals human depravity.'),
('wsc_q16_seedling', 'wsc_q16', 'seedling', 'When Adam sinned, we all became sinners.', 'Adam sinned for us all.', 'Like a leader of a team - when Adam lost, his whole team lost.'),
('wsc_q16_sprout', 'wsc_q16', 'sprout', 'Q: Did Adam''s sin affect everyone?\nA: Yes, all people born after Adam became sinners because of his sin.', 'All people became sinners.', 'Adam was like our grandfather. His mistake passed down to all of us.'),
('wsc_q16_sapling', 'wsc_q16', 'sapling', 'Q: Did all mankind fall in Adam''s first transgression?\nA: The covenant being made with Adam, not only for himself, but for his posterity; all mankind, descending from him by ordinary generation, sinned in him, and fell with him, in his first transgression.', 'All mankind sinned in Adam.', 'Adam was our "federal head" - he represented us. Define "posterity" = children and grandchildren, etc.'),
('wsc_q16_tree', 'wsc_q16', 'tree', 'Q: Did all mankind fall in Adam''s first transgression?\nA: The covenant being made with Adam, not only for himself, but for his posterity; all mankind, descending from him by ordinary generation, sinned in him, and fell with him, in his first transgression.', 'Sinned in him, fell with him.', 'Federal Headship: Adam acted as our representative. His failure is counted as our failure. This parallels Christ as second Adam.'),
('wsc_q16_oak', 'wsc_q16', 'oak', 'Q: Did all mankind fall in Adam''s first transgression?\nA: The covenant being made with Adam, not only for himself, but for his posterity; all mankind, descending from him by ordinary generation, sinned in him, and fell with him, in his first transgression.\n(Rom 5:12, 18-19, 1 Cor 15:21-22)', 'Ordinary generation.', 'Apologetics: If it seems unfair for Adam''s sin to affect us, consider: the same principle allows Christ''s righteousness to be imputed to us. Romans 5 explicitly links these two headships.'),
('wsc_q17_seedling', 'wsc_q17', 'seedling', 'After Adam sinned, people became sad and far from God.', 'Sin brings sadness.', 'Sin took away the happiness God wanted us to have. But God has a rescue plan!'),
('wsc_q17_sprout', 'wsc_q17', 'sprout', 'Q: What did the fall bring to people?\nA: Sin and misery. People became unhappy and far from God.', 'Sin and misery.', 'Sin = doing bad things. Misery = being very sad and broken.'),
('wsc_q17_sapling', 'wsc_q17', 'sapling', 'Q: Into what estate did the fall bring mankind?\nA: The fall brought mankind into an estate of sin and misery.', 'Estate of sin and misery.', 'Define "estate" = condition or state of being. We went from an estate of holiness to an estate of sin.'),
('wsc_q17_tree', 'wsc_q17', 'tree', 'Q: Into what estate did the fall bring mankind?\nA: The fall brought mankind into an estate of sin and misery.', 'Estate of sin and misery.', 'Two aspects: SIN (guilt and corruption) and MISERY (consequences and suffering). They always go together.'),
('wsc_q17_oak', 'wsc_q17', 'oak', 'Q: Into what estate did the fall bring mankind?\nA: The fall brought mankind into an estate of sin and misery.\n(Rom 5:12, Rom 3:23, Gal 3:10)', 'Sin and misery inseparable.', 'Apologetics: This explains the universality of human suffering. The world''s misery is not random but is judicially connected to human rebellion against God.'),
('wsc_q18_seedling', 'wsc_q18', 'seedling', 'Because of Adam, we are born wanting to do wrong things.', 'We are born sinners.', 'Even babies want their own way. This shows we are born with sin inside.'),
('wsc_q18_sprout', 'wsc_q18', 'sprout', 'Q: Why do people sin?\nA: Because of Adam, we have guilty hearts and want to do wrong things.', 'Guilty hearts.', 'It''s not just that we do bad things; we WANT to do bad things. Our hearts are broken.'),
('wsc_q18_sapling', 'wsc_q18', 'sapling', 'Q: Wherein consists the sinfulness of that estate whereinto man fell?\nA: The sinfulness of that estate whereinto man fell, consists in the guilt of Adam''s first sin, the want of original righteousness, and the corruption of his whole nature, which is commonly called Original Sin; together with all actual transgressions which proceed from it.', 'Guilt, want of righteousness, corruption.', 'Three parts: (1) Adam''s guilt counted as ours, (2) lack of the goodness we should have, (3) corruption that leads us to sin.'),
('wsc_q18_tree', 'wsc_q18', 'tree', 'Q: Wherein consists the sinfulness of that estate whereinto man fell?\nA: The sinfulness of that estate whereinto man fell, consists in the guilt of Adam''s first sin, the want of original righteousness, and the corruption of his whole nature, which is commonly called Original Sin; together with all actual transgressions which proceed from it.', 'Guilt, corruption, actual sins.', 'Distinguish: ORIGINAL sin (inherited from Adam) vs. ACTUAL sins (what we personally do). Both are real and damning.'),
('wsc_q18_oak', 'wsc_q18', 'oak', 'Q: Wherein consists the sinfulness of that estate whereinto man fell?\nA: The sinfulness of that estate whereinto man fell, consists in the guilt of Adam''s first sin, the want of original righteousness, and the corruption of his whole nature, which is commonly called Original Sin; together with all actual transgressions which proceed from it.\n(Rom 5:19, Rom 3:10-12, Eph 2:1-3, James 1:14-15)', 'Corruption of whole nature.', 'Apologetics: "Total Depravity" does not mean we are as bad as possible, but that sin affects every part of us (mind, will, affections). We cannot save ourselves.'),
('wsc_q19_seedling', 'wsc_q19', 'seedling', 'Sin makes us sad and hurts our friendship with God.', 'Sin hurts.', 'God is sad when we sin, and we become sad too. Sin always hurts.'),
('wsc_q19_sprout', 'wsc_q19', 'sprout', 'Q: What sad things come from sin?\nA: Sin brings anger from God, sadness, and death.', 'God''s anger, sadness, death.', 'Sin is not just breaking a rule; it makes God unhappy and brings bad things to us.'),
('wsc_q19_sapling', 'wsc_q19', 'sapling', 'Q: What is the misery of that estate whereinto man fell?\nA: All mankind by their fall lost communion with God, are under his wrath and curse, and so made liable to all miseries in this life, to death itself, and to the pains of hell forever.', 'Lost communion, wrath, death, hell.', 'List the miseries: (1) lost friendship with God, (2) under God''s anger, (3) suffering in life, (4) physical death, (5) eternal punishment.'),
('wsc_q19_tree', 'wsc_q19', 'tree', 'Q: What is the misery of that estate whereinto man fell?\nA: All mankind by their fall lost communion with God, are under his wrath and curse, and so made liable to all miseries in this life, to death itself, and to the pains of hell forever.', 'Wrath, curse, death, hell.', 'This answers why there is suffering. It is not God''s original design but the result of human rebellion. Emphasize: this is why we need a Savior!'),
('wsc_q19_oak', 'wsc_q19', 'oak', 'Q: What is the misery of that estate whereinto man fell?\nA: All mankind by their fall lost communion with God, are under his wrath and curse, and so made liable to all miseries in this life, to death itself, and to the pains of hell forever.\n(Gen 3:8, 24, Eph 2:3, Rom 6:23, Matt 25:41)', 'Pains of hell forever.', 'Apologetics: The doctrine of hell is not cruelty but justice. Infinite rebellion against an infinite God deserves infinite punishment. This magnifies the grace of salvation.'),
('wsc_q22_seedling', 'wsc_q22', 'seedling', 'Jesus, God''s Son, became a little baby for us.', 'Jesus became a baby.', 'Show a nativity scene. God became small like us so He could save us.'),
('wsc_q22_sprout', 'wsc_q22', 'sprout', 'Q: How did Jesus come to earth?\nA: Jesus was born as a baby. He had a human mommy named Mary, but God was His Father.', 'Born of Mary.', 'Jesus is special: God is His real Father, but Mary was His human mother.'),
('wsc_q22_sapling', 'wsc_q22', 'sapling', 'Q: How did Christ, being the Son of God, become man?\nA: Christ, the Son of God, became man, by taking to himself a true body, and a reasonable soul, being conceived by the power of the Holy Ghost, in the womb of the Virgin Mary, and born of her, yet without sin.', 'True body, reasonable soul, without sin.', 'Define: "Incarnation" = God becoming flesh. "Reasonable soul" = a human mind. Jesus was fully human, yet never sinned.'),
('wsc_q22_tree', 'wsc_q22', 'tree', 'Q: How did Christ, being the Son of God, become man?\nA: Christ, the Son of God, became man, by taking to himself a true body, and a reasonable soul, being conceived by the power of the Holy Ghost, in the womb of the Virgin Mary, and born of her, yet without sin.', 'Conceived by Holy Ghost, born of Mary.', 'Two natures in one person: fully God, fully man. He did not give up divinity to become human; He added humanity to His divine nature.'),
('wsc_q22_oak', 'wsc_q22', 'oak', 'Q: How did Christ, being the Son of God, become man?\nA: Christ, the Son of God, became man, by taking to himself a true body, and a reasonable soul, being conceived by the power of the Holy Ghost, in the womb of the Virgin Mary, and born of her, yet without sin.\n(Phil 2:6-7, Heb 2:14, Luke 1:35, Heb 4:15)', 'Yet without sin.', 'Apologetics: The virgin birth ensures (1) His divine nature is preserved, (2) He did not inherit Adam''s guilt. The sinlessness is essential for His role as our substitute.'),
('wsc_q23_seedling', 'wsc_q23', 'seedling', 'Jesus is our Teacher, our Priest, and our King.', 'Prophet, Priest, King.', 'Three fingers: Prophet (teaches), Priest (prays for us), King (rules).'),
('wsc_q23_sprout', 'wsc_q23', 'sprout', 'Q: What jobs does Jesus do?\nA: Jesus is our Prophet (teacher), Priest (helper), and King (ruler).', 'Prophet, Priest, King.', 'Like three jobs in one person. No one else could do all three perfectly.'),
('wsc_q23_sapling', 'wsc_q23', 'sapling', 'Q: What offices doth Christ execute as our Redeemer?\nA: Christ, as our Redeemer, doth execute the offices of a prophet, of a priest, and of a king, both in his estate of humiliation and exaltation.', 'Prophet, Priest, King.', 'In Old Testament, these were three separate roles. Only Jesus holds all three. He is the anointed One (Messiah/Christ).'),
('wsc_q23_tree', 'wsc_q23', 'tree', 'Q: What offices doth Christ execute as our Redeemer?\nA: Christ, as our Redeemer, doth execute the offices of a prophet, of a priest, and of a king, both in his estate of humiliation and exaltation.', 'Both in humiliation and exaltation.', 'He does these offices in two states: Humiliation (on earth, dying) and Exaltation (risen, ruling). He continues as Prophet, Priest, King now.'),
('wsc_q23_oak', 'wsc_q23', 'oak', 'Q: What offices doth Christ execute as our Redeemer?\nA: Christ, as our Redeemer, doth execute the offices of a prophet, of a priest, and of a king, both in his estate of humiliation and exaltation.\n(Acts 3:22, Heb 5:6, Ps 2:6, Heb 1:8)', 'Humiliation and exaltation.', 'Apologetics: The threefold office shows Christ as the fulfillment of all OT offices. This refutes any who seek prophets, priests, or kings apart from Him.'),
('wsc_q24_seedling', 'wsc_q24', 'seedling', 'Jesus tells us about God and how to be saved.', 'Jesus teaches.', 'Jesus is the best Teacher. He tells us the truth about God.'),
('wsc_q24_sprout', 'wsc_q24', 'sprout', 'Q: How is Jesus our Prophet?\nA: Jesus teaches us God''s Word and shows us how to be saved.', 'He teaches us God''s will.', 'A prophet speaks God''s words. Jesus IS God''s Word made flesh.'),
('wsc_q24_sapling', 'wsc_q24', 'sapling', 'Q: How doth Christ execute the office of a prophet?\nA: Christ executeth the office of a prophet, in revealing to us, by his word and Spirit, the will of God for our salvation.', 'By His Word and Spirit.', 'Two means: (1) The Word (Bible), (2) The Spirit (helps us understand). Both are needed for true knowledge of God.'),
('wsc_q24_tree', 'wsc_q24', 'tree', 'Q: How doth Christ execute the office of a prophet?\nA: Christ executeth the office of a prophet, in revealing to us, by his word and Spirit, the will of God for our salvation.', 'Will of God for salvation.', 'He revealed God''s will perfectly while on earth and continues through His Word and Spirit today. The Bible is His voice.'),
('wsc_q24_oak', 'wsc_q24', 'oak', 'Q: How doth Christ execute the office of a prophet?\nA: Christ executeth the office of a prophet, in revealing to us, by his word and Spirit, the will of God for our salvation.\n(John 1:18, John 15:15, John 14:26, John 20:31)', 'Revealing God''s will.', 'Apologetics: This grounds Sola Scriptura. Christ''s prophetic office means we need no other revelation. The Spirit illuminates what Christ has revealed.'),
('wsc_q25_seedling', 'wsc_q25', 'seedling', 'Jesus died to take away our sins.', 'Jesus died for me.', 'A priest brings a sacrifice to God. Jesus was both the priest AND the sacrifice.'),
('wsc_q25_sprout', 'wsc_q25', 'sprout', 'Q: How is Jesus our Priest?\nA: Jesus offered Himself to God for our sins and prays for us.', 'He offered Himself.', 'Old Testament priests offered animals. Jesus offered something better: Himself.'),
('wsc_q25_sapling', 'wsc_q25', 'sapling', 'Q: How doth Christ execute the office of a priest?\nA: Christ executeth the office of a priest, in his once offering up of himself a sacrifice to satisfy divine justice, and reconcile us to God; and in making continual intercession for us.', 'Once for all sacrifice, continual intercession.', 'Two parts: (1) Sacrifice - once, on the cross. (2) Intercession - ongoing, praying for us in heaven.'),
('wsc_q25_tree', 'wsc_q25', 'tree', 'Q: How doth Christ execute the office of a priest?\nA: Christ executeth the office of a priest, in his once offering up of himself a sacrifice to satisfy divine justice, and reconcile us to God; and in making continual intercession for us.', 'Satisfy justice, reconcile us, intercede.', 'He satisfied God''s justice (propitiation), brought us back to God (reconciliation), and continues to pray for us (intercession).'),
('wsc_q25_oak', 'wsc_q25', 'oak', 'Q: How doth Christ execute the office of a priest?\nA: Christ executeth the office of a priest, in his once offering up of himself a sacrifice to satisfy divine justice, and reconcile us to God; and in making continual intercession for us.\n(Heb 9:14, 28, Heb 2:17, Rom 8:34, Heb 7:25)', 'Once for all.', 'Apologetics: This refutes the Roman Catholic Mass as a re-sacrifice. Christ''s offering was "once" - complete and unrepeatable. His intercession ensures our perseverance.'),
('wsc_q26_seedling', 'wsc_q26', 'seedling', 'Jesus rules over everything and protects us from our enemies.', 'Jesus is King.', 'A king rules with power. Jesus is stronger than any bad guy or bully.'),
('wsc_q26_sprout', 'wsc_q26', 'sprout', 'Q: How is Jesus our King?\nA: Jesus rules us, takes care of us, and defeats our enemies.', 'He rules and protects.', 'Jesus is not a mean king. He is a loving King who cares for His people.'),
('wsc_q26_sapling', 'wsc_q26', 'sapling', 'Q: How doth Christ execute the office of a king?\nA: Christ executeth the office of a king, in subduing us to himself, in ruling and defending us, and in restraining and conquering all his and our enemies.', 'Subduing, ruling, defending, conquering.', 'Four actions: (1) Subduing us (making us willing subjects), (2) Ruling us (governing our lives), (3) Defending us (protecting us), (4) Conquering enemies.'),
('wsc_q26_tree', 'wsc_q26', 'tree', 'Q: How doth Christ execute the office of a king?\nA: Christ executeth the office of a king, in subduing us to himself, in ruling and defending us, and in restraining and conquering all his and our enemies.', 'Subduing, ruling, defending, conquering.', 'He first conquers our rebellious hearts (conversion), then rules us graciously, defends us from Satan, and will finally destroy all enemies.'),
('wsc_q26_oak', 'wsc_q26', 'oak', 'Q: How doth Christ execute the office of a king?\nA: Christ executeth the office of a king, in subduing us to himself, in ruling and defending us, and in restraining and conquering all his and our enemies.\n(Ps 110:3, Matt 2:6, Ps 2:6-9, 1 Cor 15:25)', 'All enemies conquered.', 'Apologetics: Christ reigns NOW at the Father''s right hand. His kingdom is spiritual first, but will be fully manifest at His return. All powers submit to Him.');

INSERT OR REPLACE INTO formation_progressions (
  id, formation_id, stage, simplified_content, memory_portion, parent_teaching_note
) VALUES
('wsc_q27_seedling', 'wsc_q27', 'seedling', 'Jesus left heaven and became poor for us. He even died.', 'Jesus came down for us.', 'Jesus was very rich in heaven but became very poor on earth because He loves us.'),
('wsc_q27_sprout', 'wsc_q27', 'sprout', 'Q: How did Jesus humble Himself?\nA: Jesus was born poor, suffered, died on a cross, and was buried.', 'Born, suffered, died, buried.', 'The King of heaven became a servant. He did this to save us.'),
('wsc_q27_sapling', 'wsc_q27', 'sapling', 'Q: Wherein did Christ''s humiliation consist?\nA: Christ''s humiliation consisted in his being born, and that in a low condition, made under the law, undergoing the miseries of this life, the wrath of God, and the cursed death of the cross; in being buried, and continuing under the power of death for a time.', 'Born low, made under law, wrath of God, cursed death.', 'List the steps down: (1) birth (2) low condition (3) under law (4) miseries (5) wrath (6) cross (7) burial (8) death for a time.'),
('wsc_q27_tree', 'wsc_q27', 'tree', 'Q: Wherein did Christ''s humiliation consist?\nA: Christ''s humiliation consisted in his being born, and that in a low condition, made under the law, undergoing the miseries of this life, the wrath of God, and the cursed death of the cross; in being buried, and continuing under the power of death for a time.', 'Wrath of God, cursed death.', 'He experienced every aspect of the curse we deserved. "Made under the law" means He lived the perfect life we should have lived.'),
('wsc_q27_oak', 'wsc_q27', 'oak', 'Q: Wherein did Christ''s humiliation consist?\nA: Christ''s humiliation consisted in his being born, and that in a low condition, made under the law, undergoing the miseries of this life, the wrath of God, and the cursed death of the cross; in being buried, and continuing under the power of death for a time.\n(Luke 2:7, Gal 4:4, Isa 53:3, Matt 27:46, Phil 2:8, Matt 12:40)', 'Continuing under the power of death for a time.', 'Apologetics: The humiliation was necessary for redemption. He had to take our place fully: living, suffering, dying, and being buried. Each step was purposeful.'),
('wsc_q28_seedling', 'wsc_q28', 'seedling', 'Jesus came back to life and went up to heaven to be King!', 'Jesus rose again!', 'The story doesn''t end with death. Jesus won! He''s alive forever!'),
('wsc_q28_sprout', 'wsc_q28', 'sprout', 'Q: What happened after Jesus died?\nA: He rose from the dead, went up to heaven, and sits as our King. He will come again!', 'Rose, ascended, will come again.', 'Death could not keep Jesus down. He is stronger than death!'),
('wsc_q28_sapling', 'wsc_q28', 'sapling', 'Q: Wherein consisteth Christ''s exaltation?\nA: Christ''s exaltation consisteth in his rising again from the dead on the third day, in ascending up into heaven, in sitting at the right hand of God the Father, and in coming to judge the world at the last day.', 'Rising, ascending, sitting, coming.', 'Four steps UP: (1) resurrection (2) ascension (3) session at God''s right hand (4) second coming. This is the reversal of humiliation.'),
('wsc_q28_tree', 'wsc_q28', 'tree', 'Q: Wherein consisteth Christ''s exaltation?\nA: Christ''s exaltation consisteth in his rising again from the dead on the third day, in ascending up into heaven, in sitting at the right hand of God the Father, and in coming to judge the world at the last day.', 'Sitting at God''s right hand.', 'He NOW sits at God''s right hand - the place of authority. From there He rules all things and intercedes for us.'),
('wsc_q28_oak', 'wsc_q28', 'oak', 'Q: Wherein consisteth Christ''s exaltation?\nA: Christ''s exaltation consisteth in his rising again from the dead on the third day, in ascending up into heaven, in sitting at the right hand of God the Father, and in coming to judge the world at the last day.\n(1 Cor 15:4, Acts 1:11, Mark 16:19, Acts 17:31)', 'Coming to judge the world.', 'Apologetics: The resurrection is the linchpin of Christianity. Without it, our faith is vain (1 Cor 15:17). His session at God''s right hand is not passive; He actively reigns now.'),
('wsc_q29_seedling', 'wsc_q29', 'seedling', 'The Holy Spirit makes Jesus'' gift real in our hearts.', 'The Spirit helps us.', 'Like opening a present - the Spirit helps us open and receive Jesus.'),
('wsc_q29_sprout', 'wsc_q29', 'sprout', 'Q: How do we receive what Jesus did for us?\nA: The Holy Spirit works in our hearts to give us faith.', 'The Spirit gives us faith.', 'We can''t save ourselves. The Spirit has to change our hearts first.'),
('wsc_q29_sapling', 'wsc_q29', 'sapling', 'Q: How are we made partakers of the redemption purchased by Christ?\nA: We are made partakers of the redemption purchased by Christ, by the effectual application of it to us by his Holy Spirit.', 'Effectual application by His Spirit.', 'Christ purchased salvation; the Spirit applies it. Both are essential. Define "effectual" = actually working, achieving its goal.'),
('wsc_q29_tree', 'wsc_q29', 'tree', 'Q: How are we made partakers of the redemption purchased by Christ?\nA: We are made partakers of the redemption purchased by Christ, by the effectual application of it to us by his Holy Spirit.', 'Effectual application.', 'The Spirit applies everything Christ accomplished: calling, regenerating, justifying, adopting, sanctifying, glorifying. This is the personal side of salvation.'),
('wsc_q29_oak', 'wsc_q29', 'oak', 'Q: How are we made partakers of the redemption purchased by Christ?\nA: We are made partakers of the redemption purchased by Christ, by the effectual application of it to us by his Holy Spirit.\n(John 3:5-6, Titus 3:5-6, John 1:12)', 'By His Holy Spirit.', 'Apologetics: This refutes Arminian notions that the Spirit merely offers salvation and humans complete it. The application is "effectual" - it actually accomplishes salvation in the person.'),
('wsc_q30_seedling', 'wsc_q30', 'seedling', 'The Spirit makes us believe in Jesus and join with Him.', 'Believe in Jesus.', 'Faith is like a hand that holds onto Jesus. The Spirit gives us that hand.'),
('wsc_q30_sprout', 'wsc_q30', 'sprout', 'Q: How does the Spirit save us?\nA: He makes us believe in Jesus and unites us to Him.', 'Believe and be united to Jesus.', 'The Spirit changes our hearts so we trust in Jesus and become part of His family.'),
('wsc_q30_sapling', 'wsc_q30', 'sapling', 'Q: How doth the Spirit apply to us the redemption purchased by Christ?\nA: The Spirit applieth to us the redemption purchased by Christ, by working faith in us, and thereby uniting us to Christ in our effectual calling.', 'Working faith, uniting to Christ.', 'Two actions: (1) Working faith IN us (not just offering), (2) Uniting us to Christ (we become one with Him).'),
('wsc_q30_tree', 'wsc_q30', 'tree', 'Q: How doth the Spirit apply to us the redemption purchased by Christ?\nA: The Spirit applieth to us the redemption purchased by Christ, by working faith in us, and thereby uniting us to Christ in our effectual calling.', 'Effectual calling.', 'Union with Christ is the fountain of all blessings. We receive justification, adoption, sanctification only because we are "in Christ."'),
('wsc_q30_oak', 'wsc_q30', 'oak', 'Q: How doth the Spirit apply to us the redemption purchased by Christ?\nA: The Spirit applieth to us the redemption purchased by Christ, by working faith in us, and thereby uniting us to Christ in our effectual calling.\n(Eph 1:13-14, John 15:5, 1 Cor 1:9)', 'Working faith in us.', 'Apologetics: Faith is a gift (Eph 2:8-9), not our contribution to salvation. Union with Christ is the central soteriological concept - all benefits flow from being "in Him."'),
('wsc_q31_seedling', 'wsc_q31', 'seedling', 'God calls us to come to Jesus, and we do come!', 'God calls, we come.', 'When God calls, it''s like when Mommy calls and you REALLY want to come because you love her.'),
('wsc_q31_sprout', 'wsc_q31', 'sprout', 'Q: What is God''s special call?\nA: God calls us by His Spirit. He changes our hearts so we want to come to Jesus.', 'God changes our hearts.', 'It''s not just hearing about Jesus; it''s having our hearts changed to love Him.'),
('wsc_q31_sapling', 'wsc_q31', 'sapling', 'Q: What is effectual calling?\nA: Effectual calling is the work of God''s Spirit, whereby, convincing us of our sin and misery, enlightening our minds in the knowledge of Christ, and renewing our wills, he doth persuade and enable us to embrace Jesus Christ, freely offered to us in the gospel.', 'Convincing, enlightening, renewing, persuading.', 'Four works of the Spirit: (1) Convincing of sin, (2) Enlightening with knowledge of Christ, (3) Renewing our wills, (4) Persuading and enabling us to embrace Christ.'),
('wsc_q31_tree', 'wsc_q31', 'tree', 'Q: What is effectual calling?\nA: Effectual calling is the work of God''s Spirit, whereby, convincing us of our sin and misery, enlightening our minds in the knowledge of Christ, and renewing our wills, he doth persuade and enable us to embrace Jesus Christ, freely offered to us in the gospel.', 'Freely offered in the gospel.', 'The Spirit works in the mind (enlightening), the heart (convicting), and the will (renewing). This is comprehensive transformation.'),
('wsc_q31_oak', 'wsc_q31', 'oak', 'Q: What is effectual calling?\nA: Effectual calling is the work of God''s Spirit, whereby, convincing us of our sin and misery, enlightening our minds in the knowledge of Christ, and renewing our wills, he doth persuade and enable us to embrace Jesus Christ, freely offered to us in the gospel.\n(2 Tim 1:9, 2 Thess 2:13-14, Acts 26:18, Ezek 36:26-27, John 6:44-45)', 'Persuade and enable us.', 'Apologetics: "Irresistible" doesn''t mean God drags us against our will. He changes our wills so we WANT to come. Effectual calling always accomplishes its purpose.'),
('wsc_q32_seedling', 'wsc_q32', 'seedling', 'When God calls us, He gives us good gifts: forgiveness, being His child, and becoming more like Jesus.', 'God gives good gifts.', 'List on fingers: Forgiven! God''s child! Becoming better!'),
('wsc_q32_sprout', 'wsc_q32', 'sprout', 'Q: What good things do we get when God saves us?\nA: We are made right with God, adopted into His family, and made holy.', 'Right, adopted, holy.', 'Three big gifts: (1) Justified - declared "Not Guilty," (2) Adopted - made God''s child, (3) Sanctified - made pure.'),
('wsc_q32_sapling', 'wsc_q32', 'sapling', 'Q: What benefits do they that are effectually called partake of in this life?\nA: They that are effectually called do in this life partake of justification, adoption, and sanctification, and the several benefits which in this life do either accompany or flow from them.', 'Justification, adoption, sanctification.', 'Three great gifts and all their accompanying blessings (peace, access to God, assurance, etc.).'),
('wsc_q32_tree', 'wsc_q32', 'tree', 'Q: What benefits do they that are effectually called partake of in this life?\nA: They that are effectually called do in this life partake of justification, adoption, and sanctification, and the several benefits which in this life do either accompany or flow from them.', 'In this life.', 'These are present realities, not just future hopes. Justification is our legal standing, Adoption is our relational standing, Sanctification is our practical transformation.'),
('wsc_q32_oak', 'wsc_q32', 'oak', 'Q: What benefits do they that are effectually called partake of in this life?\nA: They that are effectually called do in this life partake of justification, adoption, and sanctification, and the several benefits which in this life do either accompany or flow from them.\n(Rom 8:30, Eph 1:5, 1 Cor 1:30)', 'Accompany or flow from them.', 'Apologetics: These benefits are inseparable in application but distinguishable in concept. You cannot have one without the others. This refutes "Christian" without transformation.'),
('wsc_q33_seedling', 'wsc_q33', 'seedling', 'God says, "You are forgiven! You are good in My eyes!"', 'Forgiven by God.', 'Like a judge saying "Not guilty!" even though we did wrong. Jesus took the punishment.'),
('wsc_q33_sprout', 'wsc_q33', 'sprout', 'Q: What does it mean to be justified?\nA: God forgives our sins and says we are righteous because of Jesus.', 'Forgiven and righteous.', 'Two parts: sins forgiven AND counted as righteous. Not neutral, but fully accepted.'),
('wsc_q33_sapling', 'wsc_q33', 'sapling', 'Q: What is justification?\nA: Justification is an act of God''s free grace, wherein he pardoneth all our sins, and accepteth us as righteous in his sight, only for the righteousness of Christ imputed to us, and received by faith alone.', 'Pardoned, accepted, imputed righteousness, faith alone.', 'Key terms: (1) Pardon (forgiveness of sins), (2) Acceptance (counted righteous), (3) Imputed (credited to our account), (4) Faith alone (the instrument).'),
('wsc_q33_tree', 'wsc_q33', 'tree', 'Q: What is justification?\nA: Justification is an act of God''s free grace, wherein he pardoneth all our sins, and accepteth us as righteous in his sight, only for the righteousness of Christ imputed to us, and received by faith alone.', 'Christ''s righteousness imputed.', 'Justification is forensic (legal), not transformative. God declares us righteous; He doesn''t make us righteous (that''s sanctification). This is instantaneous and complete.'),
('wsc_q33_oak', 'wsc_q33', 'oak', 'Q: What is justification?\nA: Justification is an act of God''s free grace, wherein he pardoneth all our sins, and accepteth us as righteous in his sight, only for the righteousness of Christ imputed to us, and received by faith alone.\n(Rom 3:24-25, Rom 4:6-8, 2 Cor 5:19, 21, Rom 5:17-19, Gal 2:16, Phil 3:9)', 'Received by faith alone.', 'Apologetics: This is THE article on which the church stands or falls (Luther). Rome adds works to justification. We affirm: CHRIST''S righteousness alone, received by FAITH alone.'),
('wsc_q34_seedling', 'wsc_q34', 'seedling', 'God adopts us and becomes our loving Father.', 'God is my Father.', 'Show pictures of adoption. God chooses us to be in His family forever.'),
('wsc_q34_sprout', 'wsc_q34', 'sprout', 'Q: What is adoption?\nA: God makes us His children and gives us all the good things of His family.', 'God makes us His children.', 'Adoption means being chosen and brought into a forever family. God chose us!'),
('wsc_q34_sapling', 'wsc_q34', 'sapling', 'Q: What is adoption?\nA: Adoption is an act of God''s free grace, whereby we are received into the number, and have a right to all the privileges of the sons of God.', 'Number and privileges of sons.', 'We get the same privileges as God''s natural Son, Jesus! Access, inheritance, family name.'),
('wsc_q34_tree', 'wsc_q34', 'tree', 'Q: What is adoption?\nA: Adoption is an act of God''s free grace, whereby we are received into the number, and have a right to all the privileges of the sons of God.', 'All the privileges of sons.', 'Adoption is relational (Father-child) while justification is judicial (Judge-defendant). We receive full family rights: Abba Father, heirs of God, co-heirs with Christ.'),
('wsc_q34_oak', 'wsc_q34', 'oak', 'Q: What is adoption?\nA: Adoption is an act of God''s free grace, whereby we are received into the number, and have a right to all the privileges of the sons of God.\n(1 John 3:1, John 1:12, Rom 8:17)', 'Right to all privileges.', 'Apologetics: Adoption was legally significant in Roman culture - full inheritance rights. God''s adoption is complete and irrevocable. We cry "Abba, Father" because we truly ARE His children.'),
('wsc_q35_seedling', 'wsc_q35', 'seedling', 'God is making us more and more like Jesus.', 'Becoming like Jesus.', 'Like a plant growing toward the sun. We grow toward Jesus a little bit every day.'),
('wsc_q35_sprout', 'wsc_q35', 'sprout', 'Q: What is sanctification?\nA: God helps us to hate sin and love what is good. We become more like Jesus.', 'Hate sin, love good.', 'It''s a process. We don''t become perfect overnight, but God is working in us.'),
('wsc_q35_sapling', 'wsc_q35', 'sapling', 'Q: What is sanctification?\nA: Sanctification is the work of God''s free grace, whereby we are renewed in the whole man after the image of God, and are enabled more and more to die unto sin, and live unto righteousness.', 'Renewed, die to sin, live to righteousness.', 'Three parts: (1) Renewed in the whole man (body, mind, heart), (2) Die to sin (mortification), (3) Live to righteousness (vivification).'),
('wsc_q35_tree', 'wsc_q35', 'tree', 'Q: What is sanctification?\nA: Sanctification is the work of God''s free grace, whereby we are renewed in the whole man after the image of God, and are enabled more and more to die unto sin, and live unto righteousness.', 'More and more.', 'Sanctification is progressive, not instant. It is "the WORK" (ongoing process) vs. justification which is "an ACT" (one-time declaration).'),
('wsc_q35_oak', 'wsc_q35', 'oak', 'Q: What is sanctification?\nA: Sanctification is the work of God''s free grace, whereby we are renewed in the whole man after the image of God, and are enabled more and more to die unto sin, and live unto righteousness.\n(2 Thess 2:13, Eph 4:23-24, Rom 6:6, 14, Rom 8:4)', 'After the image of God.', 'Apologetics: This refutes both perfectionism (we''ll never be sinless in this life) and antinomianism (grace doesn''t produce change). Real faith produces real transformation.'),
('wsc_q36_seedling', 'wsc_q36', 'seedling', 'God gives us peace, love, and courage. He will never leave us.', 'God loves us always.', 'List the gifts: Peace! Love! Courage! God with us always!'),
('wsc_q36_sprout', 'wsc_q36', 'sprout', 'Q: What good things come with being saved?\nA: We have peace with God, His love, His grace, and the hope of heaven.', 'Peace, love, grace, hope.', 'These are real things we can experience right now, not just when we die.'),
('wsc_q36_sapling', 'wsc_q36', 'sapling', 'Q: What are the benefits which in this life do accompany or flow from justification, adoption, and sanctification?\nA: The benefits which in this life do accompany or flow from justification, adoption, and sanctification, are, assurance of God''s love, peace of conscience, joy in the Holy Ghost, increase of grace, and perseverance therein to the end.', 'Assurance, peace, joy, grace, perseverance.', 'Five benefits: (1) Assurance (we KNOW we are saved), (2) Peace (no more fear of judgment), (3) Joy (in the Holy Spirit), (4) Increase (growing), (5) Perseverance (we will make it!).'),
('wsc_q36_tree', 'wsc_q36', 'tree', 'Q: What are the benefits which in this life do accompany or flow from justification, adoption, and sanctification?\nA: The benefits which in this life do accompany or flow from justification, adoption, and sanctification, are, assurance of God''s love, peace of conscience, joy in the Holy Ghost, increase of grace, and perseverance therein to the end.', 'Perseverance to the end.', 'These benefits are present experiences. They may fluctuate in intensity but are possessed by all believers. Perseverance guarantees we will not finally fall away.'),
('wsc_q36_oak', 'wsc_q36', 'oak', 'Q: What are the benefits which in this life do accompany or flow from justification, adoption, and sanctification?\nA: The benefits which in this life do accompany or flow from justification, adoption, and sanctification, are, assurance of God''s love, peace of conscience, joy in the Holy Ghost, increase of grace, and perseverance therein to the end.\n(Rom 5:1-5, Rom 14:17, Prov 4:18, 1 John 5:13, 1 Peter 1:5)', 'Increase of grace.', 'Apologetics: Perseverance of the saints is grounded in God''s preserving work, not human determination. True believers will continue. Those who fall away were never truly saved (1 John 2:19).');

INSERT OR REPLACE INTO formation_progressions (
  id, formation_id, stage, simplified_content, memory_portion, parent_teaching_note
) VALUES
('wsc_q37_seedling', 'wsc_q37', 'seedling', 'When we die, we go to be with Jesus in heaven.', 'We go to Jesus.', 'Death is sad but not scary for Jesus'' people. It''s like going home to be with Him.'),
('wsc_q37_sprout', 'wsc_q37', 'sprout', 'Q: What happens to believers when they die?\nA: Our souls go to be with Jesus in heaven. We are happy forever.', 'Souls go to heaven.', 'Our bodies sleep in the ground, but our souls go straight to be with Jesus.'),
('wsc_q37_sapling', 'wsc_q37', 'sapling', 'Q: What benefits do believers receive from Christ at death?\nA: The souls of believers are at their death made perfect in holiness, and do immediately pass into glory; and their bodies, being still united to Christ, do rest in their graves till the resurrection.', 'Made perfect, pass into glory, rest till resurrection.', 'Three truths: (1) Souls are perfected instantly, (2) Souls pass immediately into glory, (3) Bodies rest united to Christ until resurrection.'),
('wsc_q37_tree', 'wsc_q37', 'tree', 'Q: What benefits do believers receive from Christ at death?\nA: The souls of believers are at their death made perfect in holiness, and do immediately pass into glory; and their bodies, being still united to Christ, do rest in their graves till the resurrection.', 'Immediately pass into glory.', 'No soul sleep, no purgatory. "To be absent from the body is to be present with the Lord" (2 Cor 5:8). The body is not abandoned but awaits resurrection.'),
('wsc_q37_oak', 'wsc_q37', 'oak', 'Q: What benefits do believers receive from Christ at death?\nA: The souls of believers are at their death made perfect in holiness, and do immediately pass into glory; and their bodies, being still united to Christ, do rest in their graves till the resurrection.\n(Heb 12:23, 2 Cor 5:1, 6, 8, Luke 23:43, Phil 1:23, 1 Thess 4:14)', 'Bodies united to Christ, resting.', 'Apologetics: This refutes (1) Soul sleep (immediate glory), (2) Purgatory (made perfect at death, not after), (3) Annihilationism (souls exist consciously). The thief on the cross was with Jesus "today."'),
('wsc_q38_seedling', 'wsc_q38', 'seedling', 'Jesus will give us new bodies that will never get sick or hurt.', 'New bodies forever.', 'Like a caterpillar becoming a butterfly, but even better. We will be healthy forever!'),
('wsc_q38_sprout', 'wsc_q38', 'sprout', 'Q: What will happen when Jesus comes back?\nA: Our bodies will rise from the dead, made perfect, and we will be with Jesus forever!', 'Bodies rise, perfect forever.', 'Our bodies will be put back together, but much better - no more crying, hurting, or dying.'),
('wsc_q38_sapling', 'wsc_q38', 'sapling', 'Q: What benefits do believers receive from Christ at the resurrection?\nA: At the resurrection, believers being raised up in glory, shall be openly acknowledged and acquitted in the day of judgment, and made perfectly blessed in the full enjoying of God to all eternity.', 'Raised in glory, acknowledged, acquitted, blessed forever.', 'Four truths: (1) Raised in glory, (2) Publicly acknowledged, (3) Openly acquitted (declared "not guilty" before everyone), (4) Perfectly blessed forever.'),
('wsc_q38_tree', 'wsc_q38', 'tree', 'Q: What benefits do believers receive from Christ at the resurrection?\nA: At the resurrection, believers being raised up in glory, shall be openly acknowledged and acquitted in the day of judgment, and made perfectly blessed in the full enjoying of God to all eternity.', 'Full enjoying of God to all eternity.', 'The final state is not just escape from hell but positive enjoyment of God. This is the ultimate fulfillment of Q1: enjoying God forever.'),
('wsc_q38_oak', 'wsc_q38', 'oak', 'Q: What benefits do believers receive from Christ at the resurrection?\nA: At the resurrection, believers being raised up in glory, shall be openly acknowledged and acquitted in the day of judgment, and made perfectly blessed in the full enjoying of God to all eternity.\n(1 Cor 15:43, Matt 10:32, Matt 25:23, 1 John 3:2, 1 Thess 4:17)', 'Raised up in glory.', 'Apologetics: Glorification is the completion of salvation. What God began in eternity past (election) culminates in eternity future (glorification). Rom 8:30: "whom He justified, them He also glorified."'),
('wsc_q39_seedling', 'wsc_q39', 'seedling', 'God wants us to obey Him.', 'Obey God.', 'Simple instruction: God gives us rules because He loves us.'),
('wsc_q39_sprout', 'wsc_q39', 'sprout', 'Q: What does God want from us?\nA: God wants us to obey His Word.', 'Obey God''s Word.', 'Connect to daily obedience: listening to parents, sharing toys.'),
('wsc_q39_sapling', 'wsc_q39', 'sapling', 'Q: What is the duty which God requireth of man?\nA: The duty which God requireth of man, is obedience to his revealed will.', 'Obedience to His revealed will.', 'Duty = What we must do. Revealed will = The Bible.'),
('wsc_q39_tree', 'wsc_q39', 'tree', 'Q: What is the duty which God requireth of man?\nA: The duty which God requireth of man, is obedience to his revealed will.', 'Obedience to His revealed will.', 'Discuss how we know what God wants (The Bible vs. Feelings).'),
('wsc_q39_oak', 'wsc_q39', 'oak', 'Q: What is the duty which God requireth of man?\nA: The duty which God requireth of man, is obedience to his revealed will.\n(Micah 6:8, 1 Sam 15:22)', 'Obedience is better than sacrifice.', 'Apologetics: Divine Command Theory. Good is what God says is good.'),
('wsc_q40_seedling', 'wsc_q40', 'seedling', 'The Bible tells us God''s rules.', 'The Bible has rules.', 'Hold up a Bible. "This book tells us how to be good."'),
('wsc_q40_sprout', 'wsc_q40', 'sprout', 'Q: Where do we find God''s rules?\nA: In the Bible.', 'The Moral Law.', 'The Bible is our rule book for life.'),
('wsc_q40_sapling', 'wsc_q40', 'sapling', 'Q: What did God at first reveal to man for the rule of his obedience?\nA: The rule which God at first revealed to man for his obedience, was the moral law.', 'The Moral Law.', 'Moral Law = Rules for what is right and wrong that never change.'),
('wsc_q40_tree', 'wsc_q40', 'tree', 'Q: What did God at first reveal to man for the rule of his obedience?\nA: The rule which God at first revealed to man for his obedience, was the moral law.', 'Revealed the moral law.', 'Written on Adam''s heart, then on stone tablets.'),
('wsc_q40_oak', 'wsc_q40', 'oak', 'Q: What did God at first reveal to man for the rule of his obedience?\nA: The rule which God at first revealed to man for his obedience, was the moral law.\n(Rom 2:14-15)', 'Moral Law.', 'Apologetics: Natural Law. Even people who don''t know the Bible know murder is wrong because God wrote it on their hearts.'),
('wsc_q41_seedling', 'wsc_q41', 'seedling', 'God gave us Ten Commandments.', 'Ten Commandments.', 'Count to ten on fingers. "God gave 10 special rules."'),
('wsc_q41_sprout', 'wsc_q41', 'sprout', 'Q: What is the Moral Law usually called?\nA: The Ten Commandments.', 'The Ten Commandments.', 'Show a picture of stone tablets.'),
('wsc_q41_sapling', 'wsc_q41', 'sapling', 'Q: Where is the moral law summarily comprehended?\nA: The moral law is summarily comprehended in the ten commandments.', 'Summarily comprehended.', 'Comprehended = Contained/Held. Summary = Short version.'),
('wsc_q41_tree', 'wsc_q41', 'tree', 'Q: Where is the moral law summarily comprehended?\nA: The moral law is summarily comprehended in the ten commandments.', 'Ten Commandments.', 'Found in Exodus 20 and Deuteronomy 5.'),
('wsc_q41_oak', 'wsc_q41', 'oak', 'Q: Where is the moral law summarily comprehended?\nA: The moral law is summarily comprehended in the ten commandments.\n(Deut 10:4)', 'The Decalogue.', 'Background: "Deca" = 10, "Logos" = Words. The Ten Words.'),
('wsc_q42_seedling', 'wsc_q42', 'seedling', 'Love God and Love Others.', 'Love God. Love People.', 'The two biggest rules. Hug yourself (Love God), extend hands (Love People).'),
('wsc_q42_sprout', 'wsc_q42', 'sprout', 'Q: What is the sum of the Ten Commandments?\nA: To love God with all our heart and our neighbor as ourselves.', 'Love God, Love Neighbor.', 'If you love God, you won''t hurt people.'),
('wsc_q42_sapling', 'wsc_q42', 'sapling', 'Q: What is the sum of the ten commandments?\nA: The sum of the ten commandments is, to love the Lord our God with all our heart, with all our soul, with all our strength, and with all our mind; and our neighbor as ourselves.', 'Love God ... and neighbor.', 'Vertical (God) and Horizontal (Neighbor) relationships.'),
('wsc_q42_tree', 'wsc_q42', 'tree', 'Q: What is the sum of the ten commandments?\nA: The sum of the ten commandments is, to love the Lord our God with all our heart, with all our soul, with all our strength, and with all our mind; and our neighbor as ourselves.', 'All heart, soul, strength, mind.', 'Total devotion required. Not half-hearted.'),
('wsc_q42_oak', 'wsc_q42', 'oak', 'Q: What is the sum of the ten commandments?\nA: The sum of the ten commandments is, to love the Lord our God with all our heart, with all our soul, with all our strength, and with all our mind; and our neighbor as ourselves.\n(Matt 22:37-40)', 'On these two hang all the law.', 'Theology: Law is not opposed to Love; Law defines what Love looks like.'),
('wsc_q43_seedling', 'wsc_q43', 'seedling', 'I am the Lord your God.', 'I am the Lord.', 'God introduces Himself before giving rules.'),
('wsc_q43_sprout', 'wsc_q43', 'sprout', 'Q: Who gave the Ten Commandments?\nA: The Lord our God, who saved His people.', 'I am the Lord thy God.', 'God reminds us He saved us before He tells us what to do.'),
('wsc_q43_sapling', 'wsc_q43', 'sapling', 'Q: What is the preface to the ten commandments?\nA: The preface to the ten commandments is in these words, I am the Lord thy God, which have brought thee out of the land of Egypt, out of the house of bondage.', 'House of bondage.', 'Bondage = Slavery. God is the Liberator.'),
('wsc_q43_tree', 'wsc_q43', 'tree', 'Q: What is the preface to the ten commandments?\nA: The preface to the ten commandments is in these words, I am the Lord thy God, which have brought thee out of the land of Egypt, out of the house of bondage.', 'I am the Lord thy God.', 'Covenant formula: "I will be your God, you will be my people."'),
('wsc_q43_oak', 'wsc_q43', 'oak', 'Q: What is the preface to the ten commandments?\nA: The preface to the ten commandments is in these words, I am the Lord thy God, which have brought thee out of the land of Egypt, out of the house of bondage.\n(Ex 20:2)', 'Brought thee out of Egypt.', 'Context: Grace precedes Law. We obey because we are saved, not to get saved.'),
('wsc_q44_seedling', 'wsc_q44', 'seedling', 'We obey God because He loves us.', 'Obey because He loves.', 'Why do we listen to Daddy? Because he takes care of us.'),
('wsc_q44_sprout', 'wsc_q44', 'sprout', 'Q: Why should we obey God''s rules?\nA: Because He is our God and He saved us.', 'He is the Lord our God.', 'God isn''t a stranger; He is OUR God.'),
('wsc_q44_sapling', 'wsc_q44', 'sapling', 'Q: What doth the preface to the ten commandments teach us?\nA: The preface to the ten commandments teacheth us, that because God is the Lord, and our God, and redeemer, therefore we are bound to keep all his commandments.', 'Bound to keep all.', 'Bound = Tied/Required. Redeemer = Savior (Buyer back).'),
('wsc_q44_tree', 'wsc_q44', 'tree', 'Q: What doth the preface to the ten commandments teach us?\nA: The preface to the ten commandments teacheth us, that because God is the Lord, and our God, and redeemer, therefore we are bound to keep all his commandments.', 'God is the Lord, and our God.', 'Motivation for obedience is gratitude, not fear.'),
('wsc_q44_oak', 'wsc_q44', 'oak', 'Q: What doth the preface to the ten commandments teach us?\nA: The preface to the ten commandments teacheth us, that because God is the Lord, and our God, and redeemer, therefore we are bound to keep all his commandments.\n(Luke 1:74-75)', 'Bound to keep.', 'Ethics: Indicative (What God did) leads to Imperative (What we must do).'),
('wsc_q45_seedling', 'wsc_q45', 'seedling', 'God is Number One.', 'No other gods.', 'Hold up 1 finger. God is first. Nothing else comes before Him.'),
('wsc_q45_sprout', 'wsc_q45', 'sprout', 'Q: What is the first commandment?\nA: Thou shalt have no other gods before me.', 'No other gods before me.', 'Don''t love toys or TV more than God.'),
('wsc_q45_sapling', 'wsc_q45', 'sapling', 'Q: What is the first commandment?\nA: The first commandment is, Thou shalt have no other gods before me.', 'Thou shalt have no other gods.', 'What is a "god"? Anything we trust or love more than the true God.'),
('wsc_q45_tree', 'wsc_q45', 'tree', 'Q: What is the first commandment?\nA: The first commandment is, Thou shalt have no other gods before me.', 'Before me.', 'In God''s sight. He sees who we truly worship.'),
('wsc_q45_oak', 'wsc_q45', 'oak', 'Q: What is the first commandment?\nA: The first commandment is, Thou shalt have no other gods before me.\n(Ex 20:3)', 'No other gods.', 'Apologetics: Polytheism vs. Monotheism. God tolerates no rivals.'),
('wsc_q46_seedling', 'wsc_q46', 'seedling', 'We must know God and love Him.', 'Know God. Love God.', 'To put God first, we have to know who He is.'),
('wsc_q46_sprout', 'wsc_q46', 'sprout', 'Q: What does the first commandment require?\nA: That we know God and worship Him only.', 'Worship Him only.', 'Worship means giving God the best place in our heart.'),
('wsc_q46_sapling', 'wsc_q46', 'sapling', 'Q: What is required in the first commandment?\nA: The first commandment requireth us to know and acknowledge God to be the only true God, and our God; and to worship and glorify him accordingly.', 'Know and acknowledge God.', 'Acknowledge = Admit/Confess. He is THE God and OUR God.'),
('wsc_q46_tree', 'wsc_q46', 'tree', 'Q: What is required in the first commandment?\nA: The first commandment requireth us to know and acknowledge God to be the only true God, and our God; and to worship and glorify him accordingly.', 'Worship and glorify him.', 'Includes private prayer and public worship.'),
('wsc_q46_oak', 'wsc_q46', 'oak', 'Q: What is required in the first commandment?\nA: The first commandment requireth us to know and acknowledge God to be the only true God, and our God; and to worship and glorify him accordingly.\n(1 Chron 28:9)', 'Only true God.', 'Theology: We must worship the correct God (Orthodoxy) correctly (Orthopraxy).');

INSERT OR REPLACE INTO formation_progressions (
  id, formation_id, stage, simplified_content, memory_portion, parent_teaching_note
) VALUES
('wsc_q47_seedling', 'wsc_q47', 'seedling', 'Do not forget God.', 'Don''t forget God.', 'It is bad to live like God isn''t there.'),
('wsc_q47_sprout', 'wsc_q47', 'sprout', 'Q: What does the first commandment forbid?\nA: Denying God or worshiping anyone else.', 'Denying God.', 'Atheists say "No God." Idolaters say "Other gods." Both are wrong.'),
('wsc_q47_sapling', 'wsc_q47', 'sapling', 'Q: What is forbidden in the first commandment?\nA: The first commandment forbiddeth the denying, or not worshiping and glorifying the true God as God, and our God; and the giving of that worship and glory to any other, which is due to him alone.', 'Giving glory to any other.', 'Idolatry is giving God''s mail to someone else.'),
('wsc_q47_tree', 'wsc_q47', 'tree', 'Q: What is forbidden in the first commandment?\nA: The first commandment forbiddeth the denying, or not worshiping and glorifying the true God as God, and our God; and the giving of that worship and glory to any other, which is due to him alone.', 'Denying the true God.', 'Practical Atheism: Living as if God doesn''t exist, even if you say you believe.'),
('wsc_q47_oak', 'wsc_q47', 'oak', 'Q: What is forbidden in the first commandment?\nA: The first commandment forbiddeth the denying, or not worshiping and glorifying the true God as God, and our God; and the giving of that worship and glory to any other, which is due to him alone.\n(Rom 1:21, Ps 14:1)', 'Worship due to Him alone.', 'Analysis: Is success, comfort, or approval an idol for you?'),
('wsc_q48_seedling', 'wsc_q48', 'seedling', 'God sees everything we do.', 'God sees me.', 'Cover eyes: "I can''t see you, but God can always see us!"'),
('wsc_q48_sprout', 'wsc_q48', 'sprout', 'Q: What does "Before Me" mean?\nA: God sees everything, even our secret thoughts.', 'God sees everything.', 'We can''t hide idols in our pockets or hearts.'),
('wsc_q48_sapling', 'wsc_q48', 'sapling', 'Q: What are we specially taught by these words [before me] in the first commandment?\nA: These words [before me] in the first commandment teach us, that God, who seeth all things, taketh notice of, and is much displeased with, the sin of having any other god.', 'God, who seeth all things.', 'Omniscient = All-seeing. God is displeased (sad/angry) when we love other things more.'),
('wsc_q48_tree', 'wsc_q48', 'tree', 'Q: What are we specially taught by these words [before me] in the first commandment?\nA: These words [before me] in the first commandment teach us, that God, who seeth all things, taketh notice of, and is much displeased with, the sin of having any other god.', 'Much displeased with.', 'Coram Deo = Living before the face of God. All life is lived in His presence.'),
('wsc_q48_oak', 'wsc_q48', 'oak', 'Q: What are we specially taught by these words [before me] in the first commandment?\nA: These words [before me] in the first commandment teach us, that God, who seeth all things, taketh notice of, and is much displeased with, the sin of having any other god.\n(Ps 44:20-21)', 'Taketh notice of.', 'Warning: Secret sins are open scandals in heaven.'),
('wsc_q49_seedling', 'wsc_q49', 'seedling', 'Do not make statues of God.', 'No statues of God.', 'We worship God with our hearts, not with statues.'),
('wsc_q49_sprout', 'wsc_q49', 'sprout', 'Q: What is the second commandment?\nA: Thou shalt not make unto thee any graven image.', 'No graven image.', 'Graven image means a carved statue to worship.'),
('wsc_q49_sapling', 'wsc_q49', 'sapling', 'Q: What is the second commandment?\nA: The second commandment is, Thou shalt not make unto thee any graven image, or any likeness of any thing that is in heaven above, or that is in the earth beneath, or that is in the water under the earth: Thou shalt not bow down thyself to them, nor serve them.', 'No graven image or likeness.', 'God is Spirit. We cannot draw Him or make Him out of wood.'),
('wsc_q49_tree', 'wsc_q49', 'tree', 'Q: What is the second commandment?\nA: The second commandment is, Thou shalt not make unto thee any graven image... for I the Lord thy God am a jealous God.', 'Jealous God.', 'Jealous means He wants all our love for Himself.'),
('wsc_q49_oak', 'wsc_q49', 'oak', 'Q: What is the second commandment?\nA: The second commandment is, Thou shalt not make unto thee any graven image... (Ex 20:4-6)', 'Not bow down nor serve them.', '1st Commandment = Who to worship. 2nd Commandment = How to worship.'),
('wsc_q50_seedling', 'wsc_q50', 'seedling', 'Worship God how He tells us.', 'Worship God''s way.', 'We don''t make up new ways to worship. We do what the Bible says.'),
('wsc_q50_sprout', 'wsc_q50', 'sprout', 'Q: What does God require in worship?\nA: To receive and keep all the worship God appointed.', 'Keep pure and entire.', 'Imagine a game; we have to play by the Rules, not cheat.'),
('wsc_q50_sapling', 'wsc_q50', 'sapling', 'Q: What is required in the second commandment?\nA: The second commandment requireth the receiving, observing, and keeping pure and entire, all such religious worship and ordinances as God hath appointed in his word.', 'Pure and entire.', 'Pure = Don''t add bad stuff. Entire = Don''t take away good stuff.'),
('wsc_q50_tree', 'wsc_q50', 'tree', 'Q: What is required in the second commandment?\nA: The second commandment requireth the receiving, observing, and keeping pure and entire, all such religious worship and ordinances as God hath appointed in his word.', 'As God hath appointed.', 'Regulative Principle of Worship: If God didn''t command it, we don''t do it in worship.'),
('wsc_q50_oak', 'wsc_q50', 'oak', 'Q: What is required in the second commandment?\nA: The second commandment requireth the receiving, observing, and keeping pure and entire, all such religious worship and ordinances as God hath appointed in his word.\n(Deut 32:46, Matt 28:20)', 'Religious worship and ordinances.', 'Includes prayer, reading scripture, preaching, sacraments, singing psalms/hymns.'),
('wsc_q51_seedling', 'wsc_q51', 'seedling', 'Don''t pray to pictures or statues.', 'No pictures of God.', 'God is too big for a picture.'),
('wsc_q51_sprout', 'wsc_q51', 'sprout', 'Q: What does God forbid in worship?\nA: Worshiping images or any way God hasn''t said.', 'Worshiping by images.', 'We don''t use pictures to help us pray.'),
('wsc_q51_sapling', 'wsc_q51', 'sapling', 'Q: What is forbidden in the second commandment?\nA: The second commandment forbiddeth the worshiping of God by images, or any other way not appointed in his word.', 'Way not appointed.', 'Will-worship: Making up our own ways to please God (like Colossians 2:23).'),
('wsc_q51_tree', 'wsc_q51', 'tree', 'Q: What is forbidden in the second commandment?\nA: The second commandment forbiddeth the worshiping of God by images, or any other way not appointed in his word.', 'Worshiping by images.', 'Why? Because images lie about God (making the Infinite look finite).'),
('wsc_q51_oak', 'wsc_q51', 'oak', 'Q: What is forbidden in the second commandment?\nA: The second commandment forbiddeth the worshiping of God by images, or any other way not appointed in his word.\n(Deut 4:15-16)', 'Way not appointed in His Word.', 'History: The Reformation removed statues to restore spiritual worship.'),
('wsc_q52_seedling', 'wsc_q52', 'seedling', 'God is the Boss of worship.', 'God is the King.', 'This is His house; He makes the rules.'),
('wsc_q52_sprout', 'wsc_q52', 'sprout', 'Q: Why must we worship God''s way?\nA: Because God is King and He is jealous for His glory.', 'God''s sovereignty.', 'Sovereignty means He is the Ruler.'),
('wsc_q52_sapling', 'wsc_q52', 'sapling', 'Q: What are the reasons annexed to the second commandment?\nA: The reasons annexed to the second commandment are, God''s sovereignty over us, his propriety in us, and the zeal he hath to his own worship.', 'Zeal he hath.', 'Zeal = Strong burning love/protection (Jealousy). Propriety = Ownership.'),
('wsc_q52_tree', 'wsc_q52', 'tree', 'Q: What are the reasons annexed to the second commandment?\nA: The reasons annexed to the second commandment are, God''s sovereignty over us, his propriety in us, and the zeal he hath to his own worship.', 'Sovereignty and Ownership.', 'We belong to Him, so we must please Him, not ourselves.'),
('wsc_q52_oak', 'wsc_q52', 'oak', 'Q: What are the reasons annexed to the second commandment?\nA: The reasons annexed to the second commandment are, God''s sovereignty over us, his propriety in us, and the zeal he hath to his own worship.\n(Ps 95:2-3, Ex 34:14)', 'Jealousy for worship.', 'God is not jealous OF us, but FOR us (protecting us from false gods).'),
('wsc_q81_seedling', 'wsc_q81', 'seedling', 'Nobody is perfect. We all disobey God sometimes.', 'We all disobey.', 'No one is perfect except Jesus. We all need help.'),
('wsc_q81_sprout', 'wsc_q81', 'sprout', 'Q: Is anyone perfect?\nA: No. Everyone sins and breaks God''s rules every day.', 'No one is perfect.', 'Even the best people sin. That is why we need a Savior.'),
('wsc_q81_sapling', 'wsc_q81', 'sapling', 'Q: Is any man able perfectly to keep the commandments of God?\nA: No mere man, since the fall, is able in this life perfectly to keep the commandments of God, but doth daily break them in thought, word, and deed.', 'Daily break them.', 'Define "mere man" (ordinary human). "In this life" means we won''t be perfect until heaven.'),
('wsc_q81_tree', 'wsc_q81', 'tree', 'Q: Is any man able perfectly to keep the commandments of God?\nA: No mere man, since the fall, is able in this life perfectly to keep the commandments of God, but doth daily break them in thought, word, and deed.', 'Break them in thought, word, and deed.', 'Sin is not just action; it is thought and word too. This shows how deep our problem is.'),
('wsc_q81_oak', 'wsc_q81', 'oak', 'Q: Is any man able perfectly to keep the commandments of God?\nA: No mere man, since the fall, is able in this life perfectly to keep the commandments of God, but doth daily break them in thought, word, and deed.\n(Eccl 7:20, 1 John 1:8, Gal 5:17, Gen 6:5)', 'No mere man since the fall.', 'Apologetics: Refutes Pelagianism/Perfectionism. "Christ" is excluded by "mere man". Perfection is impossible "in this life" due to remaining corruption.'),
('wsc_q82_seedling', 'wsc_q82', 'seedling', 'Some bad things are very big and hurt people more.', 'Some sins are bigger.', 'All sin is bad, but hitting is worse than a mean face. God sees it all.'),
('wsc_q82_sprout', 'wsc_q82', 'sprout', 'Q: Are some sins worse than others?\nA: Yes. Some sins differ in how bad they are in God''s sight.', 'Some sins are worse.', 'Stealing a cookie is bad; stealing a car is worse. Both are sin, but some do more damage.'),
('wsc_q82_sapling', 'wsc_q82', 'sapling', 'Q: Are all transgressions of the law equally heinous?\nA: Some sins in themselves, and by reason of several aggravations, are more heinous in the sight of God than others.', 'More heinous in God''s sight.', 'Define "heinous" (wicked/bad). "Aggravations" means things that make it worse (like who did it, or if it was planned).'),
('wsc_q82_tree', 'wsc_q82', 'tree', 'Q: Are all transgressions of the law equally heinous?\nA: Some sins in themselves, and by reason of several aggravations, are more heinous in the sight of God than others.', 'Some sins are more heinous.', 'While all sin damns, not all sin is equal. God judges justly according to the severity of the crime.'),
('wsc_q82_oak', 'wsc_q82', 'oak', 'Q: Are all transgressions of the law equally heinous?\nA: Some sins in themselves, and by reason of several aggravations, are more heinous in the sight of God than others.\n(John 19:11, Ezek 8:6, 13, 15, Matt 11:22-24)', 'Reason of several aggravations.', 'Apologetics: This distinction is important for justice. Subjective guilt varies based on knowledge/intent. Helps answer "is all sin the same?" (Yes in nature, No in degree).'),
('wsc_q83_seedling', 'wsc_q83', 'seedling', 'Sin brings trouble and sadness in this life and forever.', 'Sin brings trouble.', 'Sin is like touching a hot stove. It always burns.'),
('wsc_q83_sprout', 'wsc_q83', 'sprout', 'Q: What does every sin deserve?\nA: Every sin deserves God''s anger and punishment.', 'God''s anger and punishment.', 'Even small sins deserve punishment because God is so Holy.'),
('wsc_q83_sapling', 'wsc_q83', 'sapling', 'Q: What doth every sin deserve?\nA: Every sin deserveth God''s wrath and curse, both in this life, and that which is to come.', 'Wrath and curse.', 'Deserve = earn. Sin earns God''s anger now (in this life) and forever (that which is to come).'),
('wsc_q83_tree', 'wsc_q83', 'tree', 'Q: What doth every sin deserve?\nA: Every sin deserveth God''s wrath and curse, both in this life, and that which is to come.', 'Both in this life and to come.', 'This establishes the need for an infinite atonement. If every sin deserves hell, we are in big trouble without Christ.'),
('wsc_q83_oak', 'wsc_q83', 'oak', 'Q: What doth every sin deserve?\nA: Every sin deserveth God''s wrath and curse, both in this life, and that which is to come.\n(Eph 5:6, Gal 3:10, Matt 25:41, Rom 6:23)', 'Every sin deserveth.', 'Apologetics: Refutes the idea of "venial sins" (Rome) that don''t break friendship with God. ALL sin is mortal in that it deserves death. Grace alone saves us.'),
('wsc_q84_seedling', 'wsc_q84', 'seedling', 'To be safe from sin, we must trust Jesus and turn to Him.', 'Trust Jesus.', 'Jesus is our rescue boat. We must jump into the boat!'),
('wsc_q84_sprout', 'wsc_q84', 'sprout', 'Q: How do we escape God''s anger?\nA: We must believe in Jesus and be sorry for our sins.', 'Believe and be sorry.', 'Two things we need: Faith (believing) and Repentance (turning back).'),
('wsc_q84_sapling', 'wsc_q84', 'sapling', 'Q: What doth God require of us, that we may escape his wrath and curse due to us for sin?\nA: To escape the wrath and curse of God due to us for sin, God requireth of us faith in Jesus Christ, repentance unto life, with the diligent use of all the outward means whereby Christ communicateth to us the benefits of redemption.', 'Faith, repentance, use of means.', 'Three requirements: Faith, Repentance, and Means of Grace (Bible, Sacraments, Prayer).'),
('wsc_q84_tree', 'wsc_q84', 'tree', 'Q: What doth God require of us, that we may escape his wrath and curse due to us for sin?\nA: To escape the wrath and curse of God due to us for sin, God requireth of us faith in Jesus Christ, repentance unto life, with the diligent use of all the outward means whereby Christ communicateth to us the benefits of redemption.', 'Diligent use of outward means.', 'Emphasis on "Means." We don''t just sit and wait; we actively use the tools God gave us (Church, Word, Sacraments) to grow faith.'),
('wsc_q84_oak', 'wsc_q84', 'oak', 'Q: What doth God require of us, that we may escape his wrath and curse due to us for sin?\nA: To escape the wrath and curse of God due to us for sin, God requireth of us faith in Jesus Christ, repentance unto life, with the diligent use of all the outward means whereby Christ communicateth to us the benefits of redemption.\n(Acts 20:21, Prov 8:34-35, Luke 13:3, John 3:16)', 'Faith, Repentance, Means.', 'Apologetics: These are not works that earn salvation, but the instruments by which we receive it. We are saved BY grace, THROUGH faith.');

INSERT OR REPLACE INTO formation_progressions (
  id, formation_id, stage, simplified_content, memory_portion, parent_teaching_note
) VALUES
('wsc_q85_seedling', 'wsc_q85', 'seedling', 'Faith is resting on Jesus to save us.', 'Faith is trusting Jesus.', 'Lean on a chair. Faith is leaning your whole self on Jesus.'),
('wsc_q85_sprout', 'wsc_q85', 'sprout', 'Q: What does it mean to have faith?\nA: It means receiving Jesus and trusting Him alone to save us.', 'Trusting Him alone.', 'Not trusting yourself + Jesus. Just Jesus.'),
('wsc_q85_sapling', 'wsc_q85', 'sapling', 'Q: What is faith in Jesus Christ?\nA: Faith in Jesus Christ is a saving grace, whereby we receive and rest upon him alone for salvation, as he is offered to us in the gospel.', 'Receive and rest upon Him alone.', 'Two actions: Receive (take) and Rest (lean/trust). "Alone" is key - no other helpers.'),
('wsc_q85_tree', 'wsc_q85', 'tree', 'Q: What is faith in Jesus Christ?\nA: Faith in Jesus Christ is a saving grace, whereby we receive and rest upon him alone for salvation, as he is offered to us in the gospel.', 'As offered in the gospel.', 'We trust the REAL Jesus (Prophet, Priest, King) as the Bible offers Him, not a Jesus of our imagination.'),
('wsc_q85_oak', 'wsc_q85', 'oak', 'Q: What is faith in Jesus Christ?\nA: Faith in Jesus Christ is a saving grace, whereby we receive and rest upon him alone for salvation, as he is offered to us in the gospel.\n(Heb 10:39, John 1:12, Phil 3:9, Gal 2:16)', 'Saving grace.', 'Apologetics: Faith is a "grace" (gift of God), not a work of man. It is the empty hand that receives Christ.'),
('wsc_q86_seedling', 'wsc_q86', 'seedling', 'Repentance is being sorry for sin and turning back to God.', 'Turn to God.', 'Like walking the wrong way and turning around to go to Daddy.'),
('wsc_q86_sprout', 'wsc_q86', 'sprout', 'Q: What is repentance?\nA: It is being truly sorry for sin, hating it, and turning to God to obey Him.', 'Turning from sin to God.', 'Not just saying "sorry" but actually changing direction.'),
('wsc_q86_sapling', 'wsc_q86', 'sapling', 'Q: What is repentance unto life?\nA: Repentance unto life is a saving grace, whereby a sinner, out of a true sense of his sin, and apprehension of the mercy of God in Christ, doth, with grief and hatred of his sin, turn from it unto God, with full purpose of, and endeavor after, new obedience.', 'Turn from sin unto God.', 'Elements: (1) Sense of sin, (2) Seeing mercy, (3) Grief/Hatred, (4) Turning, (5) New obedience.'),
('wsc_q86_tree', 'wsc_q86', 'tree', 'Q: What is repentance unto life?\nA: Repentance unto life is a saving grace, whereby a sinner, out of a true sense of his sin, and apprehension of the mercy of God in Christ, doth, with grief and hatred of his sin, turn from it unto God, with full purpose of, and endeavor after, new obedience.', 'Apprehension of mercy.', 'We can only truly repent when we see God''s mercy. Unless we see the Cross, we just despair. Mercy melts the heart.'),
('wsc_q86_oak', 'wsc_q86', 'oak', 'Q: What is repentance unto life?\nA: Repentance unto life is a saving grace, whereby a sinner, out of a true sense of his sin, and apprehension of the mercy of God in Christ, doth, with grief and hatred of his sin, turn from it unto God, with full purpose of, and endeavor after, new obedience.\n(Acts 11:18, Acts 2:37, Joel 2:12, Jer 31:18-19, Ps 119:59)', 'Grief and hatred of sin.', 'Apologetics: Distinguish "Evangelical Repentance" (hope-filled turning) from "Legal Repentance" (fear-filled regret, like Judas). True repentance leads to life.'),
('wsc_q87_seedling', 'wsc_q87', 'seedling', 'God uses the Bible, Baptism, and Prayer to give us Jesus'' gifts.', 'Bible, Baptism, Prayer.', 'Three main tools God uses. We call them "Means of Grace."'),
('wsc_q87_sprout', 'wsc_q87', 'sprout', 'Q: How does Jesus give us salvation?\nA: By His ordinances: The Word (Bible), Sacraments, and Prayer.', 'Word, Sacraments, Prayer.', 'Ordinances = rules or tools God ordained (setup). They are special.'),
('wsc_q87_sapling', 'wsc_q87', 'sapling', 'Q: What are the outward and ordinary means whereby Christ communicateth to us the benefits of redemption?\nA: The outward and ordinary means whereby Christ communicateth to us the benefits of redemption, are his ordinances, especially the word, sacraments, and prayer; all which are made effectual to the elect for salvation.', 'Word, sacraments, prayer.', 'These are "ordinary" means - how God usually works. We shouldn''t expect miracles if we ignore these.'),
('wsc_q87_tree', 'wsc_q87', 'tree', 'Q: What are the outward and ordinary means whereby Christ communicateth to us the benefits of redemption?\nA: The outward and ordinary means whereby Christ communicateth to us the benefits of redemption, are his ordinances, especially the word, sacraments, and prayer; all which are made effectual to the elect for salvation.', 'Effectual to the elect.', 'They don''t work automatically for everyone (magically). They work for the "Elect" by the Spirit.'),
('wsc_q87_oak', 'wsc_q87', 'oak', 'Q: What are the outward and ordinary means whereby Christ communicateth to us the benefits of redemption?\nA: The outward and ordinary means whereby Christ communicateth to us the benefits of redemption, are his ordinances, especially the word, sacraments, and prayer; all which are made effectual to the elect for salvation.\n(Matt 28:19-20, Acts 2:42, 1 Cor 1:21)', 'Outward and ordinary.', 'Apologetics: Refutes "Quakerism (Word/Spirit only)" which denies outward means. God fits His grace to our nature by using physical/audible means.'),
('wsc_q88_seedling', 'wsc_q88', 'seedling', 'The Spirit uses the Bible to save us and make us good.', 'The Bible saves us.', 'The Spirit makes the words in the Bible come alive in our hearts.'),
('wsc_q88_sprout', 'wsc_q88', 'sprout', 'Q: How does the Bible help us?\nA: The Spirit uses it to show us our sin and lead us to Jesus.', 'Lead us to Jesus.', 'Reading the Bible is the best way to hear God''s voice.'),
('wsc_q88_sapling', 'wsc_q88', 'sapling', 'Q: How is the word made effectual to salvation?\nA: The Spirit of God maketh the reading, but especially the preaching of the word, an effectual means of convincing and converting sinners, and of building them up in holiness and comfort, through faith, unto salvation.', 'Reading and preaching.', 'Two ways: Reading (good) and Preaching (especially good). Preaching is God''s primary way to save people.'),
('wsc_q88_tree', 'wsc_q88', 'tree', 'Q: How is the word made effectual to salvation?\nA: The Spirit of God maketh the reading, but especially the preaching of the word, an effectual means of convincing and converting sinners, and of building them up in holiness and comfort, through faith, unto salvation.', 'Convincing and converting.', 'The Word does two things: (1) Brings us to life (converting), (2) Grows us up (building in holiness).'),
('wsc_q88_oak', 'wsc_q88', 'oak', 'Q: How is the word made effectual to salvation?\nA: The Spirit of God maketh the reading, but especially the preaching of the word, an effectual means of convincing and converting sinners, and of building them up in holiness and comfort, through faith, unto salvation.\n(Neh 8:8, 1 Cor 14:24-25, Acts 20:32, Rom 10:14-17, Rom 1:16)', 'Especially the preaching.', 'Apologetics: High view of preaching. It is not just a lecture; it is a "means of grace" where Christ speaks. Faith comes by hearing (Rom 10:17).'),
('wsc_q89_seedling', 'wsc_q89', 'seedling', 'We must listen to the Bible with love and obedience.', 'Listen with love.', 'When we read the Bible, God is talking. Shhh, listen!'),
('wsc_q89_sprout', 'wsc_q89', 'sprout', 'Q: How should we listen to God''s Word?\nA: We should prepare our hearts and listen ready to obey.', 'Listen ready to obey.', 'Don''t just hear it; do it!'),
('wsc_q89_sapling', 'wsc_q89', 'sapling', 'Q: How is the word to be read and heard, that it may become effectual to salvation?\nA: That the word may become effectual to salvation, we must attend thereunto with diligence, preparation, and prayer; receive it with faith and love, lay it up in our hearts, and practice it in our lives.', 'Diligence, preparation, prayer.', 'Before church: Prepare! During: Faith and Love. After: Practice it.'),
('wsc_q89_tree', 'wsc_q89', 'tree', 'Q: How is the word to be read and heard, that it may become effectual to salvation?\nA: That the word may become effectual to salvation, we must attend thereunto with diligence, preparation, and prayer; receive it with faith and love, lay it up in our hearts, and practice it in our lives.', 'Lay it up in hearts.', 'We must memorize and treasure it ("lay it up") so it stays with us.'),
('wsc_q89_oak', 'wsc_q89', 'oak', 'Q: How is the word to be read and heard, that it may become effectual to salvation?\nA: That the word may become effectual to salvation, we must attend thereunto with diligence, preparation, and prayer; receive it with faith and love, lay it up in our hearts, and practice it in our lives.\n(Prov 8:34, 1 Peter 2:1-2, Ps 119:11, James 1:25, Heb 4:2)', 'Practice it in our lives.', 'Apologetics: Refutes "Dead Orthodoxy" (knowing truth but not living it). The goal of the Word is transformation, not just information.'),
('wsc_q90_seedling', 'wsc_q90', 'seedling', 'Signs like water and bread don''t save us. Jesus saves us when we trust Him.', 'Jesus saves us.', 'The water is just water. Jesus uses it to teach us, but Jesus is the one who saves.'),
('wsc_q90_sprout', 'wsc_q90', 'sprout', 'Q: Do the water or bread save us?\nA: No. Only the Holy Spirit makes them work for those who have faith.', 'Spirit and faith.', 'It''s not magic. It''s the Spirit working through faith.'),
('wsc_q90_sapling', 'wsc_q90', 'sapling', 'Q: How do the sacraments become effectual means of salvation?\nA: The sacraments become effectual means of salvation, not from any virtue in them, or in him that doth administer them; but only by the blessing of Christ, and the working of his Spirit in them that by faith receive them.', 'Not from virtue in them.', 'It doesn''t matter if the pastor is super holy or not. It matters if Christ blesses it and we have faith.'),
('wsc_q90_tree', 'wsc_q90', 'tree', 'Q: How do the sacraments become effectual means of salvation?\nA: The sacraments become effectual means of salvation, not from any virtue in them, or in him that doth administer them; but only by the blessing of Christ, and the working of his Spirit in them that by faith receive them.', 'Blessing of Christ and Spirit.', 'Refutes ex opere operato (automatic working). They require the Spirit and Faith (in the receiver).'),
('wsc_q90_oak', 'wsc_q90', 'oak', 'Q: How do the sacraments become effectual means of salvation?\nA: The sacraments become effectual means of salvation, not from any virtue in them, or in him that doth administer them; but only by the blessing of Christ, and the working of his Spirit in them that by faith receive them.\n(1 Cor 3:7, 1 Peter 3:21, Rom 2:28-29, 1 Cor 12:13)', 'By faith receive them.', 'Apologetics: Refutes Romanism (Sacraments contain grace in themselves) and Donatism (validity depends on the priest''s holiness). The power is in Christ and the Spirit.'),
('wsc_q91_seedling', 'wsc_q91', 'seedling', 'A sacrament is a holy picture God gave us to see His promises.', 'A holy sign.', 'Like a ring is a sign of marriage. Sacraments are signs of God''s promise.'),
('wsc_q91_sprout', 'wsc_q91', 'sprout', 'Q: What is a sacrament?\nA: A holy sign created by Jesus to represent His love and promises.', 'Holy sign of Jesus.', 'It''s a visible word. You can see, touch, and taste God''s promise.'),
('wsc_q91_sapling', 'wsc_q91', 'sapling', 'Q: What is a sacrament?\nA: A sacrament is an holy ordinance instituted by Christ; wherein, by sensible signs, Christ, and the benefits of the new covenant, are represented, sealed, and applied to believers.', 'Instituted by Christ.', 'Only Jesus can make a sacrament. "Sensible signs" means you can sense them (see, touch, taste).'),
('wsc_q91_tree', 'wsc_q91', 'tree', 'Q: What is a sacrament?\nA: A sacrament is an holy ordinance instituted by Christ; wherein, by sensible signs, Christ, and the benefits of the new covenant, are represented, sealed, and applied to believers.', 'Represented, sealed, applied.', 'Three verbs: (1) Represent (picture it), (2) Seal (guarantee it like a wax seal), (3) Apply (give it to us).'),
('wsc_q91_oak', 'wsc_q91', 'oak', 'Q: What is a sacrament?\nA: A sacrament is an holy ordinance instituted by Christ; wherein, by sensible signs, Christ, and the benefits of the new covenant, are represented, sealed, and applied to believers.\n(Gen 17:7, 10, Ex 12, 1 Cor 11:23, 26, Rom 4:11)', 'Sensible signs.', 'Apologetics: Against "Quakerism (Word only)" - God uses physical matter (sensible signs) to confirm faith. We aren''t just spirits; we have bodies too.'),
('wsc_q92_seedling', 'wsc_q92', 'seedling', 'Baptism and the Lord''s Supper.', 'Baptism and Supper.', 'Only two. Count them: 1, 2.'),
('wsc_q92_sprout', 'wsc_q92', 'sprout', 'Q: Which are the sacraments?\nA: Baptism and the Lord''s Supper.', 'Baptism and Communion.', 'Jesus only gave us these two.'),
('wsc_q92_sapling', 'wsc_q92', 'sapling', 'Q: Which are the sacraments of the New Testament?\nA: The sacraments of the New Testament are, Baptism, and the Lord''s Supper.', 'Baptism and Lord''s Supper.', 'Old Testament had Circumcision and Passover. New Testament (now) has Baptism and Lord''s Supper.'),
('wsc_q92_tree', 'wsc_q92', 'tree', 'Q: Which are the sacraments of the New Testament?\nA: The sacraments of the New Testament are, Baptism, and the Lord''s Supper.', 'Baptism and Lord''s Supper.', 'Baptism is once (initiation). Lord''s Supper is many times (nutrition).'),
('wsc_q92_oak', 'wsc_q92', 'oak', 'Q: Which are the sacraments of the New Testament?\nA: The sacraments of the New Testament are, Baptism, and the Lord''s Supper.\n(Matt 28:19, Matt 26:26-28)', 'Only two.', 'Apologetics: Refutes Romanism (7 sacraments). Confirmation, Penance, Orders, Matrimony, Extreme Unction are NOT sacraments instituted by Christ for the whole church.'),
('wsc_q93_seedling', 'wsc_q93', 'seedling', 'Baptism is water that shows our sins are washed away by Jesus.', 'Washed by Jesus.', 'Water cleans our hands. Jesus'' blood cleans our hearts. Baptism pictures this.'),
('wsc_q93_sprout', 'wsc_q93', 'sprout', 'Q: What does baptism mean?\nA: It is washing with water in the name of the Father, Son, and Holy Spirit.', 'Washing in God''s name.', 'It marks us as belonging to God. A name tag for Christians.'),
('wsc_q93_sapling', 'wsc_q93', 'sapling', 'Q: What is baptism?\nA: Baptism is a sacrament, wherein the washing with water in the name of the Father, and of the Son, and of the Holy Ghost, doth signify and seal our ingrafting into Christ, and partaking of the benefits of the covenant of grace, and our engagement to be the Lord''s.', 'Signify and seal ingrafting.', 'It signs/seals three things: (1) Ingrafting into Christ (connected to Him), (2) Partaking of benefits, (3) Engagement (promise) to be the Lord''s.'),
('wsc_q93_tree', 'wsc_q93', 'tree', 'Q: What is baptism?\nA: Baptism is a sacrament, wherein the washing with water in the name of the Father, and of the Son, and of the Holy Ghost, doth signify and seal our ingrafting into Christ, and partaking of the benefits of the covenant of grace, and our engagement to be the Lord''s.', 'Washing with water.', 'It replaces Circumcision. It is the sign of entrance into the visible church.'),
('wsc_q93_oak', 'wsc_q93', 'oak', 'Q: What is baptism?\nA: Baptism is a sacrament, wherein the washing with water in the name of the Father, and of the Son, and of the Holy Ghost, doth signify and seal our ingrafting into Christ, and partaking of the benefits of the covenant of grace, and our engagement to be the Lord''s.\n(Matt 28:19, Rom 6:3-4, Gal 3:27)', 'Ingrafting into Christ.', 'Apologetics: Baptism is NOT just a dedication. It is a divine action of sealing. But it does not save automatically (against Rome).'),
('wsc_q94_seedling', 'wsc_q94', 'seedling', 'People who love Jesus and their babies get baptized.', 'Believers and babies.', 'Just like babies in the Old Testament got the sign, babies now get the sign too.'),
('wsc_q94_sprout', 'wsc_q94', 'sprout', 'Q: Who should be baptized?\nA: Believers and their children.', 'Believers and children.', 'If your parents love Jesus, you get His sign. If you grow up and believe, you claim it for yourself.'),
('wsc_q94_sapling', 'wsc_q94', 'sapling', 'Q: To whom is baptism to be administered?\nA: Baptism is not to be administered to any that are out of the visible church, till they profess their faith in Christ, and obedience to him; but the infants of such as are members of the visible church are to be baptized.', 'Infants of members.', 'Two groups: (1) Converts from outside (must profess faith first), (2) Infants of believers (baptized because of covenant parents).'),
('wsc_q94_tree', 'wsc_q94', 'tree', 'Q: To whom is baptism to be administered?\nA: Baptism is not to be administered to any that are out of the visible church, till they profess their faith in Christ, and obedience to him; but the infants of such as are members of the visible church are to be baptized.', 'Infants are to be baptized.', 'Argument: Covenant of Grace is the same. Promise is "to you and your children" (Acts 2:39). Circumcision included infants; Baptism does too.'),
('wsc_q94_oak', 'wsc_q94', 'oak', 'Q: To whom is baptism to be administered?\nA: Baptism is not to be administered to any that are out of the visible church, till they profess their faith in Christ, and obedience to him; but the infants of such as are members of the visible church are to be baptized.\n(Acts 2:38-39, Gen 17:7, 10, Col 2:11-12, 1 Cor 7:14, Acts 16:15, 33)', 'Infants of such as are members.', 'Apologetics: Refutes Baptists (Believer-only baptism). The new covenant is BETTER, not smalller. It would be strange to kick children out of the covenant sign without a direct command.');

INSERT OR REPLACE INTO formation_progressions (
  id, formation_id, stage, simplified_content, memory_portion, parent_teaching_note
) VALUES
('wsc_q95_seedling', 'wsc_q95', 'seedling', 'Bread and wine help us remember Jesus died for us.', 'Remember Jesus.', 'We eat and drink to say "Thank you, Jesus" and feed our souls.'),
('wsc_q95_sprout', 'wsc_q95', 'sprout', 'Q: What is the Lord''s Supper?\nA: Eating bread and drinking wine to remember Jesus'' death.', 'Remember Jesus'' death.', 'The bread is His body; the cup is His blood. Not real flesh, but a powerful picture.'),
('wsc_q95_sapling', 'wsc_q95', 'sapling', 'Q: What is the Lord''s Supper?\nA: The Lord''s Supper is a sacrament, wherein, by giving and receiving bread and wine, according to Christ''s appointment, his death is showed forth; and the worthy receivers are, not after a corporal and carnal manner, but by faith, made partakers of his body and blood, with all his benefits, to their spiritual nourishment, and growth in grace.', 'Show forth His death.', 'It is: (1) A showing forth (preaching), (2) A partaking (feeding). We actually feed on Christ spiritually.'),
('wsc_q95_tree', 'wsc_q95', 'tree', 'Q: What is the Lord''s Supper?\nA: The Lord''s Supper is a sacrament, wherein, by giving and receiving bread and wine, according to Christ''s appointment, his death is showed forth; and the worthy receivers are, not after a corporal and carnal manner, but by faith, made partakers of his body and blood, with all his benefits, to their spiritual nourishment, and growth in grace.', 'Not corporal... but by faith.', 'We deny Transubstantiation (Catholic) and Consubstantiation (Lutheran). But we affirm Real Spiritual Presence (Calvin). Christ is present by His Spirit.'),
('wsc_q95_oak', 'wsc_q95', 'oak', 'Q: What is the Lord''s Supper?\nA: The Lord''s Supper is a sacrament, wherein, by giving and receiving bread and wine, according to Christ''s appointment, his death is showed forth; and the worthy receivers are, not after a corporal and carnal manner, but by faith, made partakers of his body and blood, with all his benefits, to their spiritual nourishment, and growth in grace.\n(1 Cor 11:23-26, 1 Cor 10:16)', 'Spiritual nourishment.', 'Apologetics: Refutes Zwinglianism (mere memorial). It is more than a memory; it is a means of grace where we are nourished.'),
('wsc_q96_seedling', 'wsc_q96', 'seedling', 'We should love Jesus and be sorry for sins when we eat.', 'Love Jesus.', 'It is a special holy meal. We shouldn''t play or be silly.'),
('wsc_q96_sprout', 'wsc_q96', 'sprout', 'Q: How do we eat the Lord''s Supper?\nA: We must check our hearts, trust Jesus, and love others.', 'Check our hearts.', 'We must "examine ourselves" to make sure we are trusting Jesus.'),
('wsc_q96_sapling', 'wsc_q96', 'sapling', 'Q: What is required to the worthy receiving of the Lord''s Supper?\nA: It is required of them that would worthily partake of the Lord''s Supper, that they examine themselves of their knowledge to discern the Lord''s body, of their faith to feed upon him, of their repentance, love, and new obedience; lest, coming unworthily, they eat and drink judgment to themselves.', 'Examine themselves.', 'Self-examination areas: (1) Knowledge, (2) Faith, (3) Repentance, (4) Love, (5) New Obedience.'),
('wsc_q96_tree', 'wsc_q96', 'tree', 'Q: What is required to the worthy receiving of the Lord''s Supper?\nA: It is required of them that would worthily partake of the Lord''s Supper, that they examine themselves of their knowledge to discern the Lord''s body, of their faith to feed upon him, of their repentance, love, and new obedience; lest, coming unworthily, they eat and drink judgment to themselves.', 'Lest they eat judgment.', 'It is dangerous to play with holy things. This implies infants should not partake (paedocommunion refutation) because they cannot examine themselves.'),
('wsc_q96_oak', 'wsc_q96', 'oak', 'Q: What is required to the worthy receiving of the Lord''s Supper?\nA: It is required of them that would worthily partake of the Lord''s Supper, that they examine themselves of their knowledge to discern the Lord''s body, of their faith to feed upon him, of their repentance, love, and new obedience; lest, coming unworthily, they eat and drink judgment to themselves.\n(1 Cor 11:27-29, 2 Cor 13:5)', 'Coming unworthily.', 'Apologetics: "Worthy" does not mean "perfect" (otherwise no one could eat). It means coming in a worthy MANNER - with faith and repentance. It is for sinners, but repentant sinners.'),
('wsc_q97_seedling', 'wsc_q97', 'seedling', 'Prayer is talking to God and asking Him for things.', 'Talking to God.', 'You can talk to God anytime, anywhere.'),
('wsc_q97_sprout', 'wsc_q97', 'sprout', 'Q: What is prayer?\nA: Offering our desires to God for things that He allows, in Jesus'' name.', 'Offering desires to God.', 'We can''t ask for bad things. We ask for things agreeable to His will.'),
('wsc_q97_sapling', 'wsc_q97', 'sapling', 'Q: What is prayer?\nA: Prayer is an offering up of our desires unto God, for things agreeable to his will, in the name of Christ, with confession of our sins, and thankful acknowledgment of his mercies.', 'Offering desires in Christ''s name.', 'Parts of prayer (ACTS): Adoration (implied), Confession, Thanksgiving, Supplication (desires). Must be "in Christ''s name."'),
('wsc_q97_tree', 'wsc_q97', 'tree', 'Q: What is prayer?\nA: Prayer is an offering up of our desires unto God, for things agreeable to his will, in the name of Christ, with confession of our sins, and thankful acknowledgment of his mercies.', 'Agreeable to his will.', 'Prayer is not bending God''s will to ours, but aligning our will to His. We ask for what He has promised.'),
('wsc_q97_oak', 'wsc_q97', 'oak', 'Q: What is prayer?\nA: Prayer is an offering up of our desires unto God, for things agreeable to his will, in the name of Christ, with confession of our sins, and thankful acknowledgment of his mercies.\n(Ps 62:8, 1 John 5:14, John 16:23, Ps 32:5, Phil 4:6)', 'Confession and thanksgiving.', 'Apologetics: Prayer is relational, not mechanical. We speak to a Person, not a force.'),
('wsc_q98_seedling', 'wsc_q98', 'seedling', 'The Bible teaches us how to pray. The Lord''s Prayer is the best example.', 'The Lord''s Prayer.', 'Jesus gave us a special prayer to show us how.'),
('wsc_q98_sprout', 'wsc_q98', 'sprout', 'Q: What helps us pray?\nA: The whole Bible helps us, but especially the Lord''s Prayer.', 'The Lord''s Prayer.', 'It is the perfect pattern for prayer.'),
('wsc_q98_sapling', 'wsc_q98', 'sapling', 'Q: What rule hath God given for our direction in prayer?\nA: The whole word of God is of use to direct us in prayer; but the special rule of direction is that form of prayer which Christ taught his disciples, commonly called The Lord''s Prayer.', 'The Lord''s Prayer.', 'The Bible is the general guide; The Lord''s Prayer is the special guide.'),
('wsc_q98_tree', 'wsc_q98', 'tree', 'Q: What rule hath God given for our direction in prayer?\nA: The whole word of God is of use to direct us in prayer; but the special rule of direction is that form of prayer which Christ taught his disciples, commonly called The Lord''s Prayer.', 'Special rule of direction.', 'We can pray the Lord''s Prayer exactly, AND we can use it as a pattern (outline) for our own words.'),
('wsc_q98_oak', 'wsc_q98', 'oak', 'Q: What rule hath God given for our direction in prayer?\nA: The whole word of God is of use to direct us in prayer; but the special rule of direction is that form of prayer which Christ taught his disciples, commonly called The Lord''s Prayer.\n(2 Tim 3:16-17, Matt 6:9-13, Luke 11:2-4)', 'Commonly called the Lord''s Prayer.', 'Apologetics: Used as a pattern. It covers all necessary areas: God''s glory (Petitions 1-3) and Man''s needs (Petitions 4-6).'),
('wsc_q99_seedling', 'wsc_q99', 'seedling', 'We call God "Our Father in Heaven."', 'Our Father.', 'He is big (Heaven) but He loves us (Father).'),
('wsc_q99_sprout', 'wsc_q99', 'sprout', 'Q: How does the Lord''s Prayer obtain?\nA: "Our Father which art in heaven."', 'Our Father in heaven.', 'We come to Him as children to a father.'),
('wsc_q99_sapling', 'wsc_q99', 'sapling', 'Q: What doth the preface of the Lord''s prayer teach us?\nA: The preface of the Lord''s prayer, (which is, Our Father which art in heaven,) teacheth us to draw near to God with all holy reverence and confidence, as children to a father, able and ready to help us; and that we should pray with and for others.', 'Reverence and confidence.', 'Reverence (in heaven) + Confidence (Father). "Our" means we pray with others (church).'),
('wsc_q99_tree', 'wsc_q99', 'tree', 'Q: What doth the preface of the Lord''s prayer teach us?\nA: The preface of the Lord''s prayer, (which is, Our Father which art in heaven,) teacheth us to draw near to God with all holy reverence and confidence, as children to a father, able and ready to help us; and that we should pray with and for others.', 'Able and ready to help.', 'He is ABLE (Sovereign King) and READY (Loving Father).'),
('wsc_q99_oak', 'wsc_q99', 'oak', 'Q: What doth the preface of the Lord''s prayer teach us?\nA: The preface of the Lord''s prayer, (which is, Our Father which art in heaven,) teacheth us to draw near to God with all holy reverence and confidence, as children to a father, able and ready to help us; and that we should pray with and for others.\n(Rom 8:15, Luke 11:13, Eph 6:18)', 'Pray with and for others.', 'Apologetics: Against individualistic prayer. "Our" implies the corporate body of Christ.'),
('wsc_q100_seedling', 'wsc_q100', 'seedling', 'We want God''s name to be special and loved.', 'Hallowed be Thy Name.', 'Hallowed means "kept holy." Special.'),
('wsc_q100_sprout', 'wsc_q100', 'sprout', 'Q: What is the first thing we pray?\nA: That God''s name be honored by everyone.', 'Honor God''s name.', 'God is #1. We want everyone to know how great He is.'),
('wsc_q100_sapling', 'wsc_q100', 'sapling', 'Q: What do we pray for in the first petition?\nA: In the first petition, (which is, Hallowed be thy name,) we pray, that God would enable us and others to glorify him in all that whereby he maketh himself known; and that he would dispose all things to his own glory.', 'Glorify Him in all.', 'God''s glory is the main goal of prayer and life.'),
('wsc_q100_tree', 'wsc_q100', 'tree', 'Q: What do we pray for in the first petition?\nA: In the first petition, (which is, Hallowed be thy name,) we pray, that God would enable us and others to glorify him in all that whereby he maketh himself known; and that he would dispose all things to his own glory.', 'Dispose all things to His glory.', 'We ask God to use everything (even bad things) to bring glory to Himself.'),
('wsc_q100_oak', 'wsc_q100', 'oak', 'Q: What do we pray for in the first petition?\nA: In the first petition, (which is, Hallowed be thy name,) we pray, that God would enable us and others to glorify him in all that whereby he maketh himself known; and that he would dispose all things to his own glory.\n(Matt 6:9, Ps 67:1-3, Rom 11:36)', 'In all that whereby He maketh Himself known.', 'Apologetics: God''s name is His revelation. We must not misuse it or take it lightly.'),
('wsc_q101_seedling', 'wsc_q101', 'seedling', 'We want everyone to listen to God as King.', 'Thy Kingdom Come.', 'We want Jesus to rule in our connection and in the whole world.'),
('wsc_q101_sprout', 'wsc_q101', 'sprout', 'Q: What is the second thing we pray?\nA: That Satan''s kingdom be destroyed and Jesus'' kingdom grow.', 'Jesus'' kingdom grow.', 'We want more people to know Jesus.'),
('wsc_q101_sapling', 'wsc_q101', 'sapling', 'Q: What do we pray for in the second petition?\nA: In the second petition, (which is, Thy kingdom come,) we pray, that Satan''s kingdom may be destroyed; and that the kingdom of grace may be advanced, ourselves and others brought into it, and kept in it; and that the kingdom of glory may be hastened.', 'Kingdom of grace advanced.', 'Two kingdoms: Grace (now, in church/heart) and Glory (future, heaven). We want Grace to grow and Glory to come quickly.'),
('wsc_q101_tree', 'wsc_q101', 'tree', 'Q: What do we pray for in the second petition?\nA: In the second petition, (which is, Thy kingdom come,) we pray, that Satan''s kingdom may be destroyed; and that the kingdom of grace may be advanced, ourselves and others brought into it, and kept in it; and that the kingdom of glory may be hastened.', 'Satan''s kingdom destroyed.', 'Prayer is spiritual warfare. We ask God to smash Satan''s power and build the Church.'),
('wsc_q101_oak', 'wsc_q101', 'oak', 'Q: What do we pray for in the second petition?\nA: In the second petition, (which is, Thy kingdom come,) we pray, that Satan''s kingdom may be destroyed; and that the kingdom of grace may be advanced, ourselves and others brought into it, and kept in it; and that the kingdom of glory may be hastened.\n(Matt 6:10, Ps 68:1, Rev 22:20)', 'Kingdom of glory hastened.', 'Apologetics: Includes missions (advancing grace) and eschatology (hastening glory). We pray "Maranatha!"'),
('wsc_q102_seedling', 'wsc_q102', 'seedling', 'We want to obey God just like angels do.', 'Thy will be done.', 'Angels obey fast and happy. Help us do that too!'),
('wsc_q102_sprout', 'wsc_q102', 'sprout', 'Q: What is the third thing we pray?\nA: That we would obey God on earth just like angels do in heaven.', 'Obey like angels.', 'Angels don''t complain. They love to obey.'),
('wsc_q102_sapling', 'wsc_q102', 'sapling', 'Q: What do we pray for in the third petition?\nA: In the third petition, (which is, Thy will be done in earth, as it is in heaven,) we pray, that God, by his grace, would make us able and willing to know, obey, and submit to his will in all things, as the angels do in heaven.', 'Know, obey, and submit.', 'Active obedience (doing what He says) and Passive obedience (submitting to what He sends/allows).'),
('wsc_q102_tree', 'wsc_q102', 'tree', 'Q: What do we pray for in the third petition?\nA: In the third petition, (which is, Thy will be done in earth, as it is in heaven,) we pray, that God, by his grace, would make us able and willing to know, obey, and submit to his will in all things, as the angels do in heaven.', 'As the angels do.', 'Angels do it: Humility, Cheerfulness, Faithfulness, Diligence, Universally, Constantly. A high standard!'),
('wsc_q102_oak', 'wsc_q102', 'oak', 'Q: What do we pray for in the third petition?\nA: In the third petition, (which is, Thy will be done in earth, as it is in heaven,) we pray, that God, by his grace, would make us able and willing to know, obey, and submit to his will in all things, as the angels do in heaven.\n(Matt 6:10, Ps 103:20-21, Job 1:21)', 'Able and willing.', 'Apologetics: We are naturally unable and unwilling. We need Grace to change our wills.'),
('wsc_q103_seedling', 'wsc_q103', 'seedling', 'Please give us the food we need for today.', 'Give us daily bread.', 'We ask God for lunch, clothes, and a home. All comes from Him.'),
('wsc_q103_sprout', 'wsc_q103', 'sprout', 'Q: What is the fourth thing we pray?\nA: Give us this day our daily bread.', 'Our daily bread.', 'We ask God for what we need to live. We trust Him for today.'),
('wsc_q103_sapling', 'wsc_q103', 'sapling', 'Q: What do we pray for in the fourth petition?\nA: In the fourth petition, (which is, Give us this day our daily bread,) we pray, that of God''s free gift we may receive a competent portion of the good things of this life, and enjoy his blessing with them.', 'Competent portion.', 'Not "give us riches" but "give us enough" (competent portion). And "enjoy his blessing" - stuff without blessing is empty.'),
('wsc_q103_tree', 'wsc_q103', 'tree', 'Q: What do we pray for in the fourth petition?\nA: In the fourth petition, (which is, Give us this day our daily bread,) we pray, that of God''s free gift we may receive a competent portion of the good things of this life, and enjoy his blessing with them.', 'Good things of this life.', 'This is the only petition for physical needs. It shows our dependence on God for everything, even lunch.'),
('wsc_q103_oak', 'wsc_q103', 'oak', 'Q: What do we pray for in the fourth petition?\nA: In the fourth petition, (which is, Give us this day our daily bread,) we pray, that of God''s free gift we may receive a competent portion of the good things of this life, and enjoy his blessing with them.\n(Matt 6:11, Prov 30:8, 1 Tim 6:6-8)', 'God''s free gift.', 'Apologetics: Even if we work for money, the result is God''s gift (Deut 8:18). We pray against anxiety and for contentment.'),
('wsc_q104_seedling', 'wsc_q104', 'seedling', 'Forgive us for our bad choices, just as we forgive others.', 'Forgive our debts.', 'Debts means sins. We owe God obedience, but we failed. We need forgiveness.'),
('wsc_q104_sprout', 'wsc_q104', 'sprout', 'Q: What is the fifth thing we pray?\nA: Forgive us our debts, as we forgive our debtors.', 'Forgive as we forgive.', 'If we want God to forgive us, we must not hold grudges against others.'),
('wsc_q104_sapling', 'wsc_q104', 'sapling', 'Q: What do we pray for in the fifth petition?\nA: In the fifth petition, (which is, And forgive us our debts, as we forgive our debtors,) we pray, that God, for Christ''s sake, would freely pardon all our sins; which we are the rather encouraged to ask, because by his grace we are enabled from the heart to forgive others.', 'Pardon sins for Christ''s sake.', 'We don''t ask because we are good, but "for Christ''s sake." Evidence of grace is that we forgive others.'),
('wsc_q104_tree', 'wsc_q104', 'tree', 'Q: What do we pray for in the fifth petition?\nA: In the fifth petition, (which is, And forgive us our debts, as we forgive our debtors,) we pray, that God, for Christ''s sake, would freely pardon all our sins; which we are the rather encouraged to ask, because by his grace we are enabled from the heart to forgive others.', 'Enabled to forgive others.', 'Our forgiving others is not the CAUSE of God''s forgiveness, but the EVIDENCE (fruit) of it.'),
('wsc_q104_oak', 'wsc_q104', 'oak', 'Q: What do we pray for in the fifth petition?\nA: In the fifth petition, (which is, And forgive us our debts, as we forgive our debtors,) we pray, that God, for Christ''s sake, would freely pardon all our sins; which we are the rather encouraged to ask, because by his grace we are enabled from the heart to forgive others.\n(Matt 6:12, Matt 6:14-15, Ps 51:1, Eph 4:32)', 'Freely pardon.', 'Apologetics: We pray this daily. This proves that even justified believers still sin and need fatherly (not judicial) forgiveness daily.');

INSERT OR REPLACE INTO formation_progressions (
  id, formation_id, stage, simplified_content, memory_portion, parent_teaching_note
) VALUES
('wsc_q105_seedling', 'wsc_q105', 'seedling', 'Help us not to sin. Keep us safe from the bad one.', 'Lead us not into temptation.', 'We are weak. We need God to hold our hand so we don''t fall.'),
('wsc_q105_sprout', 'wsc_q105', 'sprout', 'Q: What is the sixth thing we pray?\nA: Lead us not into temptation, but deliver us from evil.', 'Deliver us from evil.', 'Protect us from sin and from Satan.'),
('wsc_q105_sapling', 'wsc_q105', 'sapling', 'Q: What do we pray for in the sixth petition?\nA: In the sixth petition, (which is, And lead us not into temptation, but deliver us from evil,) we pray, that God would either keep us from being tempted to sin, or support and deliver us when we are tempted.', 'Keep from, or support in.', 'Two requests: (1) Don''t let us face the test, OR (2) If we must face it, help us pass it.'),
('wsc_q105_tree', 'wsc_q105', 'tree', 'Q: What do we pray for in the sixth petition?\nA: In the sixth petition, (which is, And lead us not into temptation, but deliver us from evil,) we pray, that God would either keep us from being tempted to sin, or support and deliver us when we are tempted.', 'Deliver us when tempted.', 'God tempts no one (James 1), but He tests us and allows Satan to tempt. We pray for victory.'),
('wsc_q105_oak', 'wsc_q105', 'oak', 'Q: What do we pray for in the sixth petition?\nA: In the sixth petition, (which is, And lead us not into temptation, but deliver us from evil,) we pray, that God would either keep us from being tempted to sin, or support and deliver us when we are tempted.\n(Matt 6:13, Matt 26:41, 1 Cor 10:13, 2 Tim 4:18)', 'Keep us from being tempted.', 'Apologetics: We acknowledge our weakness. "Let him who thinks he stands take heed lest he fall." We cannot fight Satan alone.'),
('wsc_q106_seedling', 'wsc_q106', 'seedling', 'God is the King forever! Amen.', 'For Thine is the Kingdom.', 'We end by saying God is great. Amen means "Yes, it is true!"'),
('wsc_q106_sprout', 'wsc_q106', 'sprout', 'Q: How does the prayer end?\nA: For thine is the kingdom, and the power, and the glory, for ever. Amen.', 'Kingdom, power, glory.', 'All glory goes to God.'),
('wsc_q106_sapling', 'wsc_q106', 'sapling', 'Q: What doth the conclusion of the Lord''s prayer teach us?\nA: The conclusion of the Lord''s prayer, (which is, For thine is the kingdom, and the power, and the glory, for ever. Amen.) teacheth us to take our encouragement in prayer from God only, and in our prayers to praise him, ascribing kingdom, power, and glory to him; and, in testimony of our desire, and assurance to be heard, we say, Amen.', 'Kingdom, power, glory.', 'Encouragement comes from God (His power), not us (our goodness). We praise Him.'),
('wsc_q106_tree', 'wsc_q106', 'tree', 'Q: What doth the conclusion of the Lord''s prayer teach us?\nA: The conclusion of the Lord''s prayer, (which is, For thine is the kingdom, and the power, and the glory, for ever. Amen.) teacheth us to take our encouragement in prayer from God only, and in our prayers to praise him, ascribing kingdom, power, and glory to him; and, in testimony of our desire, and assurance to be heard, we say, Amen.', 'Take encouragement from God only.', 'Because the Kingdom is HIS, He cares about it. Because the Power is HIS, He can do it. Because the Glory is HIS, He will do it.'),
('wsc_q106_oak', 'wsc_q106', 'oak', 'Q: What doth the conclusion of the Lord''s prayer teach us?\nA: The conclusion of the Lord''s prayer, (which is, For thine is the kingdom, and the power, and the glory, for ever. Amen.) teacheth us to take our encouragement in prayer from God only, and in our prayers to praise him, ascribing kingdom, power, and glory to him; and, in testimony of our desire, and assurance to be heard, we say, Amen.\n(Matt 6:13, Dan 9:18-19, 1 Chron 29:11, Rev 22:20)', 'Testimony of desire and assurance.', 'Apologetics: Amen = "So let it be." It is the voice of faith sealing the prayer.');

